window.MINIGPU_RTL_SOURCES = {
  "minigpu_top.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  minigpu_top\n// File:    minigpu_top.v\n// Purpose: Top-Level Integration of 2D Graphics Processing Architecture\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule minigpu_top #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120,\n    parameter FIFO_DEPTH    = 16,\n    parameter FIFO_ADDR     = 4\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // =========================================================================\n    // 1. Host Command Interface (Handshake + Parameters)\n    // =========================================================================\n    input  wire        cmd_valid_in,\n    output wire        cmd_ready_out,\n    input  wire [1:0]  cmd_type_in,    // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [7:0]  param_x0_in,    // X0 / Rect X / Circ CX / Tri X0\n    input  wire [6:0]  param_y0_in,    // Y0 / Rect Y / Circ CY / Tri Y0\n    input  wire [7:0]  param_x1_in,    // X1 / Rect W / Circ R  / Tri X1\n    input  wire [6:0]  param_y1_in,    // Y1 / Rect H / Unused  / Tri Y1\n    input  wire [7:0]  param_x2_in,    // X2 / Unused / Unused  / Tri X2\n    input  wire [6:0]  param_y2_in,    // Y2 / Unused / Unused  / Tri Y2\n    input  wire [23:0] param_color_in, // RGB888 Color\n\n    // =========================================================================\n    // 2. Video Display Output (Raster Scanning Stream)\n    // =========================================================================\n    output wire        disp_hsync,\n    output wire        disp_vsync,\n    output wire        disp_de,\n    output wire [23:0] disp_rgb,\n    output wire [7:0]  disp_x,\n    output wire [6:0]  disp_y,\n    output wire        disp_frame_tick,\n\n    // =========================================================================\n    // 3. Telemetry & Hardware Status Signals\n    // =========================================================================\n    output wire        status_fifo_empty,\n    output wire        status_fifo_full,\n    output wire [FIFO_ADDR:0] status_fifo_count,\n    output wire        status_raster_idle,\n    output wire [2:0]  status_raster_state,\n    output wire [7:0]  status_cur_x,\n    output wire [6:0]  status_cur_y,\n    output wire        status_shape_hit,\n    output wire        status_pixel_valid,\n    output wire        status_fb_we,\n    output wire [14:0] status_fb_addr,\n    output wire [23:0] status_fb_wdata,\n    output wire [31:0] status_total_rendered,\n    output wire [15:0] status_total_cmds\n);\n\n    // -------------------------------------------------------------------------\n    // Internal Wires & Busses\n    // -------------------------------------------------------------------------\n    // Host Interface <-> FIFO\n    wire        fifo_wr_en;\n    wire [85:0] fifo_wr_data;\n    wire        fifo_rd_en;\n    wire [85:0] fifo_rd_data;\n    wire        fifo_empty;\n    wire        fifo_full;\n    wire [FIFO_ADDR:0] fifo_count;\n\n    // FIFO <-> Decoder <-> Rasterizer Controller\n    wire        raster_idle;\n    wire        cmd_done;\n    wire        dec_cmd_valid;\n    wire [1:0]  dec_cmd_type;\n    wire [7:0]  dec_shape_x0, dec_shape_x1, dec_shape_x2;\n    wire [6:0]  dec_shape_y0, dec_shape_y1, dec_shape_y2;\n    wire [23:0] dec_shape_color;\n    wire [7:0]  dec_bbox_min_x, dec_bbox_max_x;\n    wire [6:0]  dec_bbox_min_y, dec_bbox_max_y;\n\n    // Rasterizer Controller <-> Shape Rasterizers\n    wire        eval_enable;\n    wire [7:0]  cur_pixel_x;\n    wire [6:0]  cur_pixel_y;\n    wire        rect_hit;\n    wire        circ_hit;\n    wire        tri_hit;\n    reg         active_shape_hit;\n\n    // Pixel Color Generator\n    wire        gen_pixel_valid;\n    wire [23:0] gen_pixel_color;\n\n    // Framebuffer Port A (Render Write)\n    wire        fb_we;\n    wire [14:0] fb_waddr;\n    wire [23:0] fb_wdata;\n\n    // Framebuffer Port B (Display Read)\n    wire        fb_re_b;\n    wire [14:0] fb_raddr_b;\n    wire [23:0] fb_rdata_b;\n\n    // -------------------------------------------------------------------------\n    // 1. Host Command Interface\n    // -------------------------------------------------------------------------\n    cmd_interface u_cmd_interface (\n        .clk            (clk),\n        .rst_n          (rst_n),\n        .cmd_valid_in   (cmd_valid_in),\n        .cmd_ready_out  (cmd_ready_out),\n        .cmd_type_in    (cmd_type_in),\n        .param_x0_in    (param_x0_in),\n        .param_y0_in    (param_y0_in),\n        .param_x1_in    (param_x1_in),\n        .param_y1_in    (param_y1_in),\n        .param_x2_in    (param_x2_in),\n        .param_y2_in    (param_y2_in),\n        .param_color_in (param_color_in),\n        .fifo_full      (fifo_full),\n        .fifo_wr_en     (fifo_wr_en),\n        .fifo_wr_data   (fifo_wr_data)\n    );\n\n    // -------------------------------------------------------------------------\n    // 2. Command FIFO Buffer\n    // -------------------------------------------------------------------------\n    command_fifo #(\n        .DEPTH     (FIFO_DEPTH),\n        .WIDTH     (86),\n        .ADDR_BITS (FIFO_ADDR)\n    ) u_command_fifo (\n        .clk       (clk),\n        .rst_n     (rst_n),\n        .wr_en     (fifo_wr_en),\n        .wr_data   (fifo_wr_data),\n        .rd_en     (fifo_rd_en),\n        .rd_data   (fifo_rd_data),\n        .empty     (fifo_empty),\n        .full      (fifo_full),\n        .count     (fifo_count)\n    );\n\n    // -------------------------------------------------------------------------\n    // 3. Command Decoder & Range Validator\n    // -------------------------------------------------------------------------\n    command_decoder #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_command_decoder (\n        .clk           (clk),\n        .rst_n         (rst_n),\n        .fifo_empty    (fifo_empty),\n        .fifo_data     (fifo_rd_data),\n        .fifo_rd_en    (fifo_rd_en),\n        .raster_idle   (raster_idle),\n        .cmd_done      (cmd_done),\n        .cmd_valid_out (dec_cmd_valid),\n        .cmd_type_out  (dec_cmd_type),\n        .shape_x0      (dec_shape_x0),\n        .shape_y0      (dec_shape_y0),\n        .shape_x1      (dec_shape_x1),\n        .shape_y1      (dec_shape_y1),\n        .shape_x2      (dec_shape_x2),\n        .shape_y2      (dec_shape_y2),\n        .shape_color   (dec_shape_color),\n        .bbox_min_x    (dec_bbox_min_x),\n        .bbox_max_x    (dec_bbox_max_x),\n        .bbox_min_y    (dec_bbox_min_y),\n        .bbox_max_y    (dec_bbox_max_y)\n    );\n\n    // -------------------------------------------------------------------------\n    // 4. Shape Rasterization Submodules\n    // -------------------------------------------------------------------------\n    rectangle_rasterizer #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_rect_rasterizer (\n        .enable        (eval_enable && (dec_cmd_type == 2'b00)),\n        .cur_x         (cur_pixel_x),\n        .cur_y         (cur_pixel_y),\n        .rect_x        (dec_shape_x0),\n        .rect_y        (dec_shape_y0),\n        .rect_w        (dec_shape_x1),\n        .rect_h        (dec_shape_y1),\n        .hit           (rect_hit)\n    );\n\n    circle_rasterizer #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_circ_rasterizer (\n        .enable        (eval_enable && (dec_cmd_type == 2'b01)),\n        .cur_x         (cur_pixel_x),\n        .cur_y         (cur_pixel_y),\n        .circ_cx       (dec_shape_x0),\n        .circ_cy       (dec_shape_y0),\n        .circ_r        (dec_shape_x1),\n        .hit           (circ_hit)\n    );\n\n    triangle_rasterizer #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_tri_rasterizer (\n        .enable        (eval_enable && (dec_cmd_type == 2'b10)),\n        .cur_x         (cur_pixel_x),\n        .cur_y         (cur_pixel_y),\n        .v0_x          (dec_shape_x0),\n        .v0_y          (dec_shape_y0),\n        .v1_x          (dec_shape_x1),\n        .v1_y          (dec_shape_y1),\n        .v2_x          (dec_shape_x2),\n        .v2_y          (dec_shape_y2),\n        .hit           (tri_hit)\n    );\n\n    // Active shape hit multiplexer\n    always @(*) begin\n        case (dec_cmd_type)\n            2'b00:   active_shape_hit = rect_hit;\n            2'b01:   active_shape_hit = circ_hit;\n            2'b10:   active_shape_hit = tri_hit;\n            2'b11:   active_shape_hit = 1'b1; // Clear screen fills entire bbox\n            default: active_shape_hit = 1'b0;\n        endcase\n    end\n\n    // -------------------------------------------------------------------------\n    // 5. Pixel Color Generator\n    // -------------------------------------------------------------------------\n    pixel_color_generator u_color_gen (\n        .cmd_type      (dec_cmd_type),\n        .shape_color   (dec_shape_color),\n        .shape_hit     (active_shape_hit),\n        .pixel_valid   (gen_pixel_valid),\n        .pixel_color   (gen_pixel_color)\n    );\n\n    // -------------------------------------------------------------------------\n    // 6. Rasterization Controller\n    // -------------------------------------------------------------------------\n    rasterizer_controller #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_raster_controller (\n        .clk           (clk),\n        .rst_n         (rst_n),\n        .cmd_valid     (dec_cmd_valid),\n        .cmd_type      (dec_cmd_type),\n        .bbox_min_x    (dec_bbox_min_x),\n        .bbox_max_x    (dec_bbox_max_x),\n        .bbox_min_y    (dec_bbox_min_y),\n        .bbox_max_y    (dec_bbox_max_y),\n        .shape_color   (dec_shape_color),\n        .cmd_done      (cmd_done),\n        .eval_enable   (eval_enable),\n        .cur_pixel_x   (cur_pixel_x),\n        .cur_pixel_y   (cur_pixel_y),\n        .shape_hit     (active_shape_hit),\n        .pixel_valid   (gen_pixel_valid),\n        .fb_ready      (1'b1), // Dual-port SRAM always ready\n        .fb_we         (fb_we),\n        .fb_addr       (fb_waddr),\n        .fb_data       (fb_wdata),\n        .raster_idle   (raster_idle),\n        .raster_state  (status_raster_state),\n        .total_pixels_rendered (status_total_rendered),\n        .total_commands_done   (status_total_cmds)\n    );\n\n    // -------------------------------------------------------------------------\n    // 7. Dual-Port Synchronous Framebuffer Memory (19,200 x 24-bit)\n    // -------------------------------------------------------------------------\n    framebuffer #(\n        .WIDTH     (24),\n        .SIZE      (SCREEN_WIDTH * SCREEN_HEIGHT),\n        .ADDR_BITS (15)\n    ) u_framebuffer (\n        .clk       (clk),\n        .rst_n     (rst_n),\n        // Port A: Render Write\n        .we_a      (fb_we),\n        .addr_a    (fb_waddr),\n        .din_a     (fb_wdata),\n        // Port B: Display Read\n        .re_b      (fb_re_b),\n        .addr_b    (fb_raddr_b),\n        .dout_b    (fb_rdata_b)\n    );\n\n    // -------------------------------------------------------------------------\n    // 8. Virtual Display Controller & Raster Scanner\n    // -------------------------------------------------------------------------\n    display_controller #(\n        .H_ACTIVE  (SCREEN_WIDTH),\n        .V_ACTIVE  (SCREEN_HEIGHT)\n    ) u_display_ctrl (\n        .clk            (clk),\n        .rst_n          (rst_n),\n        .fb_read_addr   (fb_raddr_b),\n        .fb_read_en     (fb_re_b),\n        .fb_read_data   (fb_rdata_b),\n        .disp_x         (disp_x),\n        .disp_y         (disp_y),\n        .rgb_out        (disp_rgb),\n        .hsync          (disp_hsync),\n        .vsync          (disp_vsync),\n        .display_enable (disp_de),\n        .frame_tick     (disp_frame_tick)\n    );\n\n    // -------------------------------------------------------------------------\n    // 9. Status & Telemetry Wiring\n    // -------------------------------------------------------------------------\n    assign status_fifo_empty   = fifo_empty;\n    assign status_fifo_full    = fifo_full;\n    assign status_fifo_count   = fifo_count;\n    assign status_raster_idle  = raster_idle;\n    assign status_cur_x        = cur_pixel_x;\n    assign status_cur_y        = cur_pixel_y;\n    assign status_shape_hit    = active_shape_hit;\n    assign status_pixel_valid  = gen_pixel_valid;\n    assign status_fb_we        = fb_we;\n    assign status_fb_addr      = fb_waddr;\n    assign status_fb_wdata     = fb_wdata;\n\nendmodule\n",
  "cmd_interface.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  cmd_interface\n// File:    cmd_interface.v\n// Purpose: Host Command Interface with Ready/Valid Handshake & FIFO Packing\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule cmd_interface (\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Host interface ports\n    input  wire        cmd_valid_in,\n    output wire        cmd_ready_out,\n    input  wire [1:0]  cmd_type_in,    // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [7:0]  param_x0_in,    // X0 / Rect X / Circ CX / Tri X0\n    input  wire [6:0]  param_y0_in,    // Y0 / Rect Y / Circ CY / Tri Y0\n    input  wire [7:0]  param_x1_in,    // X1 / Rect W / Circ R  / Tri X1\n    input  wire [6:0]  param_y1_in,    // Y1 / Rect H / Unused  / Tri Y1\n    input  wire [7:0]  param_x2_in,    // X2 / Unused / Unused  / Tri X2\n    input  wire [6:0]  param_y2_in,    // Y2 / Unused / Unused  / Tri Y2\n    input  wire [23:0] param_color_in, // RGB888 Color\n\n    // Command FIFO write interface\n    input  wire        fifo_full,\n    output wire        fifo_wr_en,\n    output wire [85:0] fifo_wr_data\n);\n\n    // MiniGPU is ready to accept host commands when FIFO is not full\n    assign cmd_ready_out = !fifo_full;\n\n    // Write to FIFO on valid handshake\n    assign fifo_wr_en = cmd_valid_in && cmd_ready_out;\n\n    // Pack 86-bit command packet\n    // [85:84] : Command type (2 bits)\n    // [83:76] : X0 (8 bits)\n    // [75:69] : Y0 (7 bits)\n    // [68:61] : X1 (8 bits)\n    // [60:54] : Y1 (7 bits)\n    // [53:46] : X2 (8 bits)\n    // [45:39] : Y2 (7 bits)\n    // [38:15] : Color RGB888 (24 bits)\n    // [14:0]  : Reserved (15 bits)\n    assign fifo_wr_data = {\n        cmd_type_in,     // [85:84]\n        param_x0_in,     // [83:76]\n        param_y0_in,     // [75:69]\n        param_x1_in,     // [68:61]\n        param_y1_in,     // [60:54]\n        param_x2_in,     // [53:46]\n        param_y2_in,     // [45:39]\n        param_color_in,  // [38:15]\n        15'd0            // [14:0]\n    };\n\nendmodule\n",
  "command_fifo.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  command_fifo\n// File:    command_fifo.v\n// Purpose: Synchronous Circular FIFO for Host Drawing Commands\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule command_fifo #(\n    parameter DEPTH     = 16,\n    parameter WIDTH     = 86,\n    parameter ADDR_BITS = 4\n)(\n    input  wire                  clk,\n    input  wire                  rst_n,\n\n    // Write Port\n    input  wire                  wr_en,\n    input  wire [WIDTH-1:0]      wr_data,\n\n    // Read Port\n    input  wire                  rd_en,\n    output wire [WIDTH-1:0]      rd_data,\n\n    // Status Flags\n    output wire                  empty,\n    output wire                  full,\n    output reg  [ADDR_BITS:0]    count\n);\n\n    reg [WIDTH-1:0]     mem [0:DEPTH-1];\n    reg [ADDR_BITS-1:0] wr_ptr;\n    reg [ADDR_BITS-1:0] rd_ptr;\n\n    assign empty = (count == {(ADDR_BITS+1){1'b0}});\n    assign full  = (count == DEPTH);\n\n    // Read data directly available at head of FIFO\n    assign rd_data = mem[rd_ptr];\n\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            wr_ptr <= {ADDR_BITS{1'b0}};\n            rd_ptr <= {ADDR_BITS{1'b0}};\n            count  <= {(ADDR_BITS+1){1'b0}};\n            for (i = 0; i < DEPTH; i = i + 1) begin\n                mem[i] <= {WIDTH{1'b0}};\n            end\n        end else begin\n            // Write action\n            if (wr_en && !full) begin\n                mem[wr_ptr] <= wr_data;\n                wr_ptr      <= (wr_ptr == DEPTH - 1) ? {ADDR_BITS{1'b0}} : wr_ptr + 1'b1;\n            end\n\n            // Read action\n            if (rd_en && !empty) begin\n                rd_ptr <= (rd_ptr == DEPTH - 1) ? {ADDR_BITS{1'b0}} : rd_ptr + 1'b1;\n            end\n\n            // Counter update\n            case ({wr_en && !full, rd_en && !empty})\n                2'b10: count <= count + 1'b1;\n                2'b01: count <= count - 1'b1;\n                default: count <= count; // 2'b00 or 2'b11 (simultaneous r/w)\n            endcase\n        end\n    end\n\nendmodule\n",
  "command_decoder.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  command_decoder\n// File:    command_decoder.v\n// Purpose: Hardware Command Decoding, Parameter Validation & Bounding-Box Setup\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule command_decoder #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Interface with Command FIFO\n    input  wire        fifo_empty,\n    input  wire [85:0] fifo_data,\n    output reg         fifo_rd_en,\n\n    // Interface with Rasterizer Controller\n    input  wire        raster_idle,\n    input  wire        cmd_done,\n    output reg         cmd_valid_out,\n    output reg  [1:0]  cmd_type_out,\n\n    // Unpacked Shape Coordinates\n    output reg  [7:0]  shape_x0,\n    output reg  [6:0]  shape_y0,\n    output reg  [7:0]  shape_x1,\n    output reg  [6:0]  shape_y1,\n    output reg  [7:0]  shape_x2,\n    output reg  [6:0]  shape_y2,\n    output reg  [23:0] shape_color,\n\n    // Clipped Bounding-Box Limits\n    output reg  [7:0]  bbox_min_x,\n    output reg  [7:0]  bbox_max_x,\n    output reg  [6:0]  bbox_min_y,\n    output reg  [6:0]  bbox_max_y\n);\n\n    // Unpack raw fields from FIFO packet\n    wire [1:0]  raw_type  = fifo_data[85:84];\n    wire [7:0]  raw_x0    = fifo_data[83:76];\n    wire [6:0]  raw_y0    = fifo_data[75:69];\n    wire [7:0]  raw_x1    = fifo_data[68:61];\n    wire [6:0]  raw_y1    = fifo_data[60:54];\n    wire [7:0]  raw_x2    = fifo_data[53:46];\n    wire [6:0]  raw_y2    = fifo_data[45:39];\n    wire [23:0] raw_color = fifo_data[38:15];\n\n    // Combinational Bounding-Box Calculation\n    reg [7:0] calc_min_x;\n    reg [7:0] calc_max_x;\n    reg [6:0] calc_min_y;\n    reg [6:0] calc_max_y;\n\n    // Helper functions for min/max\n    function [7:0] min3_8(input [7:0] a, input [7:0] b, input [7:0] c);\n        reg [7:0] m;\n        begin\n            m = (a < b) ? a : b;\n            min3_8 = (m < c) ? m : c;\n        end\n    endfunction\n\n    function [7:0] max3_8(input [7:0] a, input [7:0] b, input [7:0] c);\n        reg [7:0] m;\n        begin\n            m = (a > b) ? a : b;\n            max3_8 = (m > c) ? m : c;\n        end\n    endfunction\n\n    function [6:0] min3_7(input [6:0] a, input [6:0] b, input [6:0] c);\n        reg [6:0] m;\n        begin\n            m = (a < b) ? a : b;\n            min3_7 = (m < c) ? m : c;\n        end\n    endfunction\n\n    function [6:0] max3_7(input [6:0] a, input [6:0] b, input [6:0] c);\n        reg [6:0] m;\n        begin\n            m = (a > b) ? a : b;\n            max3_7 = (m > c) ? m : c;\n        end\n    endfunction\n\n    always @(*) begin\n        case (raw_type)\n            2'b00: begin // Rectangle: X, Y, Width, Height\n                calc_min_x = (raw_x0 < SCREEN_WIDTH) ? raw_x0 : 8'd0;\n                calc_max_x = (({1'b0, raw_x0} + {1'b0, raw_x1}) > SCREEN_WIDTH) ? \n                             8'd159 : (raw_x1 > 8'd0 ? raw_x0 + raw_x1 - 1'b1 : raw_x0);\n                calc_min_y = (raw_y0 < SCREEN_HEIGHT) ? raw_y0 : 7'd0;\n                calc_max_y = (({1'b0, raw_y0} + {1'b0, raw_y1}) > SCREEN_HEIGHT) ? \n                             7'd119 : (raw_y1 > 7'd0 ? raw_y0 + raw_y1 - 1'b1 : raw_y0);\n            end\n\n            2'b01: begin // Circle: Center X, Center Y, Radius\n                calc_min_x = (raw_x0 >= raw_x1) ? (raw_x0 - raw_x1) : 8'd0;\n                calc_max_x = (({1'b0, raw_x0} + {1'b0, raw_x1}) > 9'd159) ? 8'd159 : (raw_x0 + raw_x1);\n                calc_min_y = (raw_y0 >= raw_x1[6:0]) ? (raw_y0 - raw_x1[6:0]) : 7'd0;\n                calc_max_y = (({1'b0, raw_y0} + {1'b0, raw_x1[6:0]}) > 8'd119) ? 7'd119 : (raw_y0 + raw_x1[6:0]);\n            end\n\n            2'b10: begin // Triangle: V0(x0,y0), V1(x1,y1), V2(x2,y2)\n                calc_min_x = min3_8(raw_x0, raw_x1, raw_x2);\n                calc_max_x = (max3_8(raw_x0, raw_x1, raw_x2) < SCREEN_WIDTH) ? \n                              max3_8(raw_x0, raw_x1, raw_x2) : 8'd159;\n                calc_min_y = min3_7(raw_y0, raw_y1, raw_y2);\n                calc_max_y = (max3_7(raw_y0, raw_y1, raw_y2) < SCREEN_HEIGHT) ? \n                              max3_7(raw_y0, raw_y1, raw_y2) : 7'd119;\n            end\n\n            2'b11: begin // Clear Screen (Full Framebuffer)\n                calc_min_x = 8'd0;\n                calc_max_x = 8'd159;\n                calc_min_y = 7'd0;\n                calc_max_y = 7'd119;\n            end\n        endcase\n    end\n\n    // FSM for Decoder Dispatches\n    localparam DEC_IDLE = 2'b00;\n    localparam DEC_WAIT = 2'b01;\n    localparam DEC_POP  = 2'b10;\n\n    reg [1:0] dec_state;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            dec_state     <= DEC_IDLE;\n            fifo_rd_en    <= 1'b0;\n            cmd_valid_out <= 1'b0;\n            cmd_type_out  <= 2'b00;\n            shape_x0      <= 8'd0;\n            shape_y0      <= 7'd0;\n            shape_x1      <= 8'd0;\n            shape_y1      <= 7'd0;\n            shape_x2      <= 8'd0;\n            shape_y2      <= 7'd0;\n            shape_color   <= 24'd0;\n            bbox_min_x    <= 8'd0;\n            bbox_max_x    <= 8'd0;\n            bbox_min_y    <= 7'd0;\n            bbox_max_y    <= 7'd0;\n        end else begin\n            fifo_rd_en <= 1'b0; // Default pulse\n\n            case (dec_state)\n                DEC_IDLE: begin\n                    cmd_valid_out <= 1'b0;\n                    if (!fifo_empty && raster_idle) begin\n                        cmd_type_out  <= raw_type;\n                        shape_x0      <= raw_x0;\n                        shape_y0      <= raw_y0;\n                        shape_x1      <= raw_x1;\n                        shape_y1      <= raw_y1;\n                        shape_x2      <= raw_x2;\n                        shape_y2      <= raw_y2;\n                        shape_color   <= raw_color;\n                        bbox_min_x    <= calc_min_x;\n                        bbox_max_x    <= calc_max_x;\n                        bbox_min_y    <= calc_min_y;\n                        bbox_max_y    <= calc_max_y;\n\n                        cmd_valid_out <= 1'b1;\n                        dec_state     <= DEC_WAIT;\n                    end\n                end\n\n                DEC_WAIT: begin\n                    if (cmd_done) begin\n                        cmd_valid_out <= 1'b0;\n                        fifo_rd_en    <= 1'b1; // Dequeue command from FIFO\n                        dec_state     <= DEC_POP;\n                    end else if (!raster_idle) begin\n                        cmd_valid_out <= 1'b0; // Rasterizer has acknowledged\n                    end\n                end\n\n                DEC_POP: begin\n                    fifo_rd_en <= 1'b0;\n                    dec_state  <= DEC_IDLE; // Allow 1 clock cycle for FIFO to advance rd_ptr\n                end\n\n                default: dec_state <= DEC_IDLE;\n            endcase\n        end\n    end\n\nendmodule\n",
  "rasterizer_controller.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  rasterizer_controller\n// File:    rasterizer_controller.v\n// Purpose: Hardware Rasterization FSM, Coordinate Traversal & Pixel Dispatch\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule rasterizer_controller #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Command Interface from Decoder\n    input  wire        cmd_valid,\n    input  wire [1:0]  cmd_type,       // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [7:0]  bbox_min_x,\n    input  wire [7:0]  bbox_max_x,\n    input  wire [6:0]  bbox_min_y,\n    input  wire [6:0]  bbox_max_y,\n    input  wire [23:0] shape_color,\n    output reg         cmd_done,\n\n    // Interface to Shape Rasterizers\n    output reg         eval_enable,\n    output reg  [7:0]  cur_pixel_x,\n    output reg  [6:0]  cur_pixel_y,\n    input  wire        shape_hit,      // Hit result from active rasterizer\n    input  wire        pixel_valid,    // Qualified pixel from pixel_color_generator\n\n    // Framebuffer Write Interface (Port A)\n    input  wire        fb_ready,       // Framebuffer memory ready / no stall\n    output reg         fb_we,\n    output reg  [14:0] fb_addr,\n    output reg  [23:0] fb_data,\n\n    // Status and Telemetry\n    output wire        raster_idle,\n    output reg  [2:0]  raster_state,\n    output reg  [31:0] total_pixels_rendered,\n    output reg  [15:0] total_commands_done\n);\n\n    // FSM State Encoding\n    localparam STATE_IDLE      = 3'b000;\n    localparam STATE_SETUP     = 3'b001;\n    localparam STATE_RASTERIZE = 3'b010;\n    localparam STATE_WRITE     = 3'b011;\n    localparam STATE_COMPLETE  = 3'b100;\n\n    assign raster_idle = (raster_state == STATE_IDLE);\n\n    // Latched command boundaries and attributes\n    reg [1:0]  latched_type;\n    reg [7:0]  latched_min_x, latched_max_x;\n    reg [6:0]  latched_min_y, latched_max_y;\n    reg [23:0] latched_color;\n\n    // Framebuffer address arithmetic: y * 160 + x = (y << 7) + (y << 5) + x\n    wire [14:0] calc_addr = ({8'd0, cur_pixel_y} << 7) + \n                            ({8'd0, cur_pixel_y} << 5) + \n                            {7'd0, cur_pixel_x};\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            raster_state          <= STATE_IDLE;\n            eval_enable           <= 1'b0;\n            cur_pixel_x           <= 8'd0;\n            cur_pixel_y           <= 7'd0;\n            fb_we                 <= 1'b0;\n            fb_addr               <= 15'd0;\n            fb_data               <= 24'd0;\n            cmd_done              <= 1'b0;\n            latched_type          <= 2'b00;\n            latched_min_x         <= 8'd0;\n            latched_max_x         <= 8'd0;\n            latched_min_y         <= 7'd0;\n            latched_max_y         <= 7'd0;\n            latched_color         <= 24'd0;\n            total_pixels_rendered <= 32'd0;\n            total_commands_done   <= 16'd0;\n        end else begin\n            cmd_done <= 1'b0; // Default pulse\n            fb_we    <= 1'b0; // Default no-write\n\n            case (raster_state)\n                STATE_IDLE: begin\n                    eval_enable <= 1'b0;\n                    if (cmd_valid) begin\n                        latched_type  <= cmd_type;\n                        latched_min_x <= bbox_min_x;\n                        latched_max_x <= bbox_max_x;\n                        latched_min_y <= bbox_min_y;\n                        latched_max_y <= bbox_max_y;\n                        latched_color <= shape_color;\n                        raster_state  <= STATE_SETUP;\n                    end\n                end\n\n                STATE_SETUP: begin\n                    // Initialize scan cursor to top-left of clipped bounding box\n                    cur_pixel_x  <= latched_min_x;\n                    cur_pixel_y  <= latched_min_y;\n                    eval_enable  <= 1'b1;\n                    raster_state <= STATE_RASTERIZE;\n                end\n\n                STATE_RASTERIZE: begin\n                    eval_enable <= 1'b1;\n\n                    // Evaluate if current pixel is covered\n                    if (pixel_valid && fb_ready) begin\n                        // Dispatch write to Framebuffer Port A\n                        fb_we                 <= 1'b1;\n                        fb_addr               <= calc_addr;\n                        fb_data               <= latched_color;\n                        total_pixels_rendered <= total_pixels_rendered + 1'b1;\n                    end\n\n                    // Advance coordinates (scanline traversal)\n                    if (cur_pixel_x < latched_max_x) begin\n                        cur_pixel_x <= cur_pixel_x + 1'b1;\n                    end else begin\n                        cur_pixel_x <= latched_min_x;\n                        if (cur_pixel_y < latched_max_y) begin\n                            cur_pixel_y <= cur_pixel_y + 1'b1;\n                        end else begin\n                            // Reached end of bounding box\n                            eval_enable  <= 1'b0;\n                            raster_state <= STATE_COMPLETE;\n                        end\n                    end\n                end\n\n                STATE_COMPLETE: begin\n                    eval_enable         <= 1'b0;\n                    cmd_done            <= 1'b1;\n                    total_commands_done <= total_commands_done + 1'b1;\n                    raster_state        <= STATE_IDLE;\n                end\n\n                default: raster_state <= STATE_IDLE;\n            endcase\n        end\n    end\n\nendmodule\n",
  "rectangle_rasterizer.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  rectangle_rasterizer\n// File:    rectangle_rasterizer.v\n// Purpose: Hardware Rectangle Coverage & Clipping Rasterizer\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule rectangle_rasterizer #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire       enable,\n    input  wire [7:0] cur_x,\n    input  wire [6:0] cur_y,\n    input  wire [7:0] rect_x,\n    input  wire [6:0] rect_y,\n    input  wire [7:0] rect_w,\n    input  wire [6:0] rect_h,\n    output wire       hit\n);\n\n    wire [8:0] right_edge  = {1'b0, rect_x} + {1'b0, rect_w};\n    wire [7:0] bottom_edge = {1'b0, rect_y} + {1'b0, rect_h};\n\n    wire inside_x = (cur_x >= rect_x) && ({1'b0, cur_x} < right_edge);\n    wire inside_y = (cur_y >= rect_y) && ({1'b0, cur_y} < bottom_edge);\n    wire valid_screen = (cur_x < SCREEN_WIDTH) && (cur_y < SCREEN_HEIGHT);\n\n    assign hit = enable && inside_x && inside_y && valid_screen && (rect_w > 8'd0) && (rect_h > 7'd0);\n\nendmodule\n",
  "circle_rasterizer.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  circle_rasterizer\n// File:    circle_rasterizer.v\n// Purpose: Hardware Circle Coverage Engine with Squared-Distance Arithmetic\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule circle_rasterizer #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire       enable,\n    input  wire [7:0] cur_x,\n    input  wire [6:0] cur_y,\n    input  wire [7:0] circ_cx,\n    input  wire [6:0] circ_cy,\n    input  wire [7:0] circ_r,\n    output wire       hit\n);\n\n    // Compute signed offsets from circle center\n    wire signed [9:0] dx = $signed({2'b00, cur_x}) - $signed({2'b00, circ_cx});\n    wire signed [9:0] dy = $signed({3'b000, cur_y}) - $signed({3'b000, circ_cy});\n\n    // Compute squared terms with 20-bit precision (prevents any overflow)\n    wire [19:0] dx_sq   = $unsigned(dx * dx);\n    wire [19:0] dy_sq   = $unsigned(dy * dy);\n    wire [19:0] dist_sq = dx_sq + dy_sq;\n    wire [19:0] r_sq    = $unsigned({12'd0, circ_r} * {12'd0, circ_r});\n\n    wire valid_screen = (cur_x < SCREEN_WIDTH) && (cur_y < SCREEN_HEIGHT);\n\n    // Coverage test: dx^2 + dy^2 <= r^2\n    assign hit = enable && valid_screen && (dist_sq <= r_sq);\n\nendmodule\n",
  "triangle_rasterizer.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  triangle_rasterizer\n// File:    triangle_rasterizer.v\n// Purpose: Pineda Edge-Function Triangle Rasterizer (Signed Fixed-Point)\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule triangle_rasterizer #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire       enable,\n    input  wire [7:0] cur_x,\n    input  wire [6:0] cur_y,\n    input  wire [7:0] v0_x,\n    input  wire [6:0] v0_y,\n    input  wire [7:0] v1_x,\n    input  wire [6:0] v1_y,\n    input  wire [7:0] v2_x,\n    input  wire [6:0] v2_y,\n    output wire       hit\n);\n\n    // Signed extension for vertices and current coordinate\n    wire signed [10:0] px = $signed({3'b000, cur_x});\n    wire signed [10:0] py = $signed({4'b0000, cur_y});\n\n    wire signed [10:0] x0 = $signed({3'b000, v0_x});\n    wire signed [10:0] y0 = $signed({4'b0000, v0_y});\n    wire signed [10:0] x1 = $signed({3'b000, v1_x});\n    wire signed [10:0] y1 = $signed({4'b0000, v1_y});\n    wire signed [10:0] x2 = $signed({3'b000, v2_x});\n    wire signed [10:0] y2 = $signed({4'b0000, v2_y});\n\n    // Edge vectors\n    wire signed [10:0] dx01 = x1 - x0;\n    wire signed [10:0] dy01 = y1 - y0;\n\n    wire signed [10:0] dx12 = x2 - x1;\n    wire signed [10:0] dy12 = y2 - y1;\n\n    wire signed [10:0] dx20 = x0 - x2;\n    wire signed [10:0] dy20 = y0 - y2;\n\n    // Cross products for edge functions\n    // E01(p) = (px - x0) * dy01 - (py - y0) * dx01\n    // E12(p) = (px - x1) * dy12 - (py - y1) * dx12\n    // E20(p) = (px - x2) * dy20 - (py - y2) * dx20\n    wire signed [21:0] e01 = (px - x0) * dy01 - (py - y0) * dx01;\n    wire signed [21:0] e12 = (px - x1) * dy12 - (py - y1) * dx12;\n    wire signed [21:0] e20 = (px - x2) * dy20 - (py - y2) * dx20;\n\n    // Triangle winding check: all positive or all negative\n    wire all_pos = (e01 >= 22'sd0) && (e12 >= 22'sd0) && (e20 >= 22'sd0);\n    wire all_neg = (e01 <= 22'sd0) && (e12 <= 22'sd0) && (e20 <= 22'sd0);\n\n    // Reject degenerate triangles where all 3 vertices are collinear or identical\n    wire non_degenerate = (e01 != 22'sd0) || (e12 != 22'sd0) || (e20 != 22'sd0);\n\n    wire valid_screen = (cur_x < SCREEN_WIDTH) && (cur_y < SCREEN_HEIGHT);\n\n    assign hit = enable && valid_screen && (all_pos || all_neg) && non_degenerate;\n\nendmodule\n",
  "pixel_color_generator.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  pixel_color_generator\n// File:    pixel_color_generator.v\n// Purpose: Hardware Pixel Color Formatting & Qualification\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule pixel_color_generator (\n    input  wire [1:0]  cmd_type,       // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [23:0] shape_color,    // RGB888 Color\n    input  wire        shape_hit,      // Hit from active rasterizer\n    output wire        pixel_valid,    // Qualified pixel ready to write\n    output wire [23:0] pixel_color     // Qualified 24-bit RGB\n);\n\n    // For Clear command (2'b11), every pixel in the screen grid is valid.\n    // For Shapes (2'b00, 2'b01, 2'b10), only pixels that pass the coverage test are valid.\n    wire is_clear = (cmd_type == 2'b11);\n\n    assign pixel_valid = is_clear || shape_hit;\n    assign pixel_color = shape_color;\n\nendmodule\n",
  "framebuffer.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  framebuffer\n// File:    framebuffer.v\n// Purpose: True Dual-Port Synchronous Video Memory (19,200 x 24-bit RGB888)\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule framebuffer #(\n    parameter WIDTH     = 24,\n    parameter SIZE      = 19200,   // 160 x 120 pixels\n    parameter ADDR_BITS = 15       // 2^15 = 32768 > 19200\n)(\n    input  wire                 clk,\n    input  wire                 rst_n,\n\n    // Port A: Render Write Port\n    input  wire                 we_a,\n    input  wire [ADDR_BITS-1:0] addr_a,\n    input  wire [WIDTH-1:0]     din_a,\n\n    // Port B: Display Read Port\n    input  wire                 re_b,\n    input  wire [ADDR_BITS-1:0] addr_b,\n    output reg  [WIDTH-1:0]     dout_b\n);\n\n    // Synthesizable RAM block\n    reg [WIDTH-1:0] mem [0:SIZE-1];\n\n    integer i;\n\n    // Port A Write Operation\n    always @(posedge clk) begin\n        if (we_a && (addr_a < SIZE)) begin\n            mem[addr_a] <= din_a;\n        end\n    end\n\n    // Port B Read Operation (Synchronous 1-cycle read latency)\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            dout_b <= {WIDTH{1'b0}};\n        end else begin\n            if (re_b) begin\n                if (addr_b < SIZE) begin\n                    dout_b <= mem[addr_b];\n                end else begin\n                    dout_b <= {WIDTH{1'b0}};\n                end\n            end\n        end\n    end\n\n    // Power-up initialization for simulation\n    initial begin\n        for (i = 0; i < SIZE; i = i + 1) begin\n            mem[i] = {WIDTH{1'b0}};\n        end\n    end\n\nendmodule\n",
  "display_controller.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  display_controller\n// File:    display_controller.v\n// Purpose: Virtual Display Raster Timing Generator & Framebuffer Port B Scanner\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule display_controller #(\n    // Virtual Display Timing Parameters (160 x 120 Resolution)\n    parameter H_ACTIVE      = 160,\n    parameter H_FRONT_PORCH = 8,\n    parameter H_SYNC        = 16,\n    parameter H_BACK_PORCH  = 16,\n    parameter H_TOTAL       = 200, // 160 + 8 + 16 + 16\n\n    parameter V_ACTIVE      = 120,\n    parameter V_FRONT_PORCH = 2,\n    parameter V_SYNC        = 4,\n    parameter V_BACK_PORCH  = 4,\n    parameter V_TOTAL       = 130  // 120 + 2 + 4 + 4\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Framebuffer Port B Interface\n    output wire [14:0] fb_read_addr,\n    output wire        fb_read_en,\n    input  wire [23:0] fb_read_data,\n\n    // Display Output Signals\n    output reg  [7:0]  disp_x,\n    output reg  [6:0]  disp_y,\n    output reg  [23:0] rgb_out,\n    output reg         hsync,\n    output reg         vsync,\n    output reg         display_enable,\n    output reg         frame_tick\n);\n\n    // Scan counters\n    reg [7:0] h_count; // 0 .. 199\n    reg [7:0] v_count; // 0 .. 129\n\n    // Pre-fetch coordinate logic (1 clock cycle ahead to match SRAM read latency)\n    wire [7:0] next_h = (h_count == H_TOTAL - 1) ? 8'd0 : h_count + 1'b1;\n    wire [7:0] next_v = (h_count == H_TOTAL - 1) ? \n                        ((v_count == V_TOTAL - 1) ? 8'd0 : v_count + 1'b1) : v_count;\n\n    wire next_active = (next_h < H_ACTIVE) && (next_v < V_ACTIVE);\n\n    // Framebuffer read address: next_v * 160 + next_h = (next_v << 7) + (next_v << 5) + next_h\n    assign fb_read_addr = ({8'd0, next_v[6:0]} << 7) + \n                          ({8'd0, next_v[6:0]} << 5) + \n                          {7'd0, next_h};\n\n    assign fb_read_en = next_active;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            h_count        <= 8'd0;\n            v_count        <= 8'd0;\n            disp_x         <= 8'd0;\n            disp_y         <= 7'd0;\n            rgb_out        <= 24'd0;\n            hsync          <= 1'b1;\n            vsync          <= 1'b1;\n            display_enable <= 1'b0;\n            frame_tick     <= 1'b0;\n        end else begin\n            // Advance horizontal and vertical scan counters\n            if (h_count == H_TOTAL - 1) begin\n                h_count <= 8'd0;\n                if (v_count == V_TOTAL - 1) begin\n                    v_count    <= 8'd0;\n                    frame_tick <= 1'b1; // New frame pulse\n                end else begin\n                    v_count    <= v_count + 1'b1;\n                    frame_tick <= 1'b0;\n                end\n            end else begin\n                h_count    <= h_count + 1'b1;\n                frame_tick <= 1'b0;\n            end\n\n            // Horizontal sync (active low during sync interval)\n            hsync <= !( (h_count >= H_ACTIVE + H_FRONT_PORCH) && \n                        (h_count <  H_ACTIVE + H_FRONT_PORCH + H_SYNC) );\n\n            // Vertical sync (active low during sync interval)\n            vsync <= !( (v_count >= V_ACTIVE + V_FRONT_PORCH) && \n                        (v_count <  V_ACTIVE + V_FRONT_PORCH + V_SYNC) );\n\n            // Display enable (active during visible frame region)\n            display_enable <= (h_count < H_ACTIVE) && (v_count < V_ACTIVE);\n\n            // Output coordinates and pixel color\n            if (h_count < H_ACTIVE && v_count < V_ACTIVE) begin\n                disp_x  <= h_count;\n                disp_y  <= v_count[6:0];\n                rgb_out <= fb_read_data; // Framebuffer data arrived 1 cycle after address\n            end else begin\n                disp_x  <= 8'd0;\n                disp_y  <= 7'd0;\n                rgb_out <= 24'd0; // Blanking during porch/sync intervals\n            end\n        end\n    end\n\nendmodule\n",
  "tb_minigpu_top.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  tb_minigpu_top\n// File:    tb_minigpu_top.v\n// Purpose: Comprehensive Testbench & Hardware Verification Suite\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_minigpu_top;\n\n    reg         clk;\n    reg         rst_n;\n\n    // Host Command Interface\n    reg         cmd_valid_in;\n    wire        cmd_ready_out;\n    reg  [1:0]  cmd_type_in;\n    reg  [7:0]  param_x0_in;\n    reg  [6:0]  param_y0_in;\n    reg  [7:0]  param_x1_in;\n    reg  [6:0]  param_y1_in;\n    reg  [7:0]  param_x2_in;\n    reg  [6:0]  param_y2_in;\n    reg  [23:0] param_color_in;\n\n    // Video Output\n    wire        disp_hsync;\n    wire        disp_vsync;\n    wire        disp_de;\n    wire [23:0] disp_rgb;\n    wire [7:0]  disp_x;\n    wire [6:0]  disp_y;\n    wire        disp_frame_tick;\n\n    // Status Signals\n    wire        status_fifo_empty;\n    wire        status_fifo_full;\n    wire [4:0]  status_fifo_count;\n    wire        status_raster_idle;\n    wire [2:0]  status_raster_state;\n    wire [7:0]  status_cur_x;\n    wire [6:0]  status_cur_y;\n    wire        status_shape_hit;\n    wire        status_pixel_valid;\n    wire        status_fb_we;\n    wire [14:0] status_fb_addr;\n    wire [23:0] status_fb_wdata;\n    wire [31:0] status_total_rendered;\n    wire [15:0] status_total_cmds;\n\n    // Instantiate Device Under Test (DUT)\n    minigpu_top #(\n        .SCREEN_WIDTH  (160),\n        .SCREEN_HEIGHT (120),\n        .FIFO_DEPTH    (16),\n        .FIFO_ADDR     (4)\n    ) dut (\n        .clk                   (clk),\n        .rst_n                 (rst_n),\n        .cmd_valid_in          (cmd_valid_in),\n        .cmd_ready_out         (cmd_ready_out),\n        .cmd_type_in           (cmd_type_in),\n        .param_x0_in           (param_x0_in),\n        .param_y0_in           (param_y0_in),\n        .param_x1_in           (param_x1_in),\n        .param_y1_in           (param_y1_in),\n        .param_x2_in           (param_x2_in),\n        .param_y2_in           (param_y2_in),\n        .param_color_in        (param_color_in),\n        .disp_hsync            (disp_hsync),\n        .disp_vsync            (disp_vsync),\n        .disp_de               (disp_de),\n        .disp_rgb              (disp_rgb),\n        .disp_x                (disp_x),\n        .disp_y                (disp_y),\n        .disp_frame_tick       (disp_frame_tick),\n        .status_fifo_empty     (status_fifo_empty),\n        .status_fifo_full      (status_fifo_full),\n        .status_fifo_count     (status_fifo_count),\n        .status_raster_idle    (status_raster_idle),\n        .status_raster_state   (status_raster_state),\n        .status_cur_x          (status_cur_x),\n        .status_cur_y          (status_cur_y),\n        .status_shape_hit      (status_shape_hit),\n        .status_pixel_valid    (status_pixel_valid),\n        .status_fb_we          (status_fb_we),\n        .status_fb_addr        (status_fb_addr),\n        .status_fb_wdata       (status_fb_wdata),\n        .status_total_rendered (status_total_rendered),\n        .status_total_cmds     (status_total_cmds)\n    );\n\n    // Clock Generation: 50 MHz simulation clock (20ns period)\n    always #10 clk = ~clk;\n\n    // Verification statistics\n    integer tests_passed = 0;\n    integer tests_failed = 0;\n\n    // Helper task to send drawing command\n    task send_command(\n        input [1:0]  c_type,\n        input [7:0]  x0, input [6:0] y0,\n        input [7:0]  x1, input [6:0] y1,\n        input [7:0]  x2, input [6:0] y2,\n        input [23:0] color\n    );\n        begin\n            @(posedge clk);\n            while (!cmd_ready_out) @(posedge clk);\n            cmd_valid_in   <= 1'b1;\n            cmd_type_in    <= c_type;\n            param_x0_in    <= x0;\n            param_y0_in    <= y0;\n            param_x1_in    <= x1;\n            param_y1_in    <= y1;\n            param_x2_in    <= x2;\n            param_y2_in    <= y2;\n            param_color_in <= color;\n            @(posedge clk);\n            cmd_valid_in   <= 1'b0;\n        end\n    endtask\n\n    // Helper task to wait until rasterizer finishes all commands\n    task wait_idle();\n        begin\n            repeat (3) @(posedge clk);\n            while (!status_fifo_empty || !status_raster_idle) @(posedge clk);\n            repeat (5) @(posedge clk);\n        end\n    endtask\n\n    // Helper function to read framebuffer pixel\n    function [23:0] read_pixel(input [7:0] x, input [6:0] y);\n        integer addr;\n        begin\n            addr = y * 160 + x;\n            read_pixel = dut.u_framebuffer.mem[addr];\n        end\n    endfunction\n\n    initial begin\n        $dumpfile(\"minigpu_sim.vcd\");\n        $dumpvars(0, tb_minigpu_top);\n\n        $display(\"=================================================================\");\n        $display(\"   ECRIONIX MINIGPU - CYCLE-ACCURATE RTL VERIFICATION SUITE      \");\n        $display(\"=================================================================\");\n\n        clk            = 0;\n        rst_n          = 0;\n        cmd_valid_in   = 0;\n        cmd_type_in    = 0;\n        param_x0_in    = 0;\n        param_y0_in    = 0;\n        param_x1_in    = 0;\n        param_y1_in    = 0;\n        param_x2_in    = 0;\n        param_y2_in    = 0;\n        param_color_in = 0;\n\n        // Apply Reset\n        #40;\n        rst_n = 1;\n        #20;\n\n        // ---------------------------------------------------------------------\n        // TEST 1: Clear Screen (Black Background #000000)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 1] Clear Screen with Background #000000...\");\n        send_command(2'b11, 8'd0, 7'd0, 8'd0, 7'd0, 8'd0, 7'd0, 24'h000000);\n        wait_idle();\n\n        if (read_pixel(0, 0) == 24'h000000 && \n            read_pixel(80, 60) == 24'h000000 && \n            read_pixel(159, 119) == 24'h000000) begin\n            $display(\"  -> PASS: Screen cleared to black (19,200 pixels initialized).\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Screen clear verification error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 2: Red Rectangle (X=20, Y=20, W=40, H=30, Color=#FF0000)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 2] Red Rectangle Rasterization (20,20 to 59,49)...\");\n        send_command(2'b00, 8'd20, 7'd20, 8'd40, 7'd30, 8'd0, 7'd0, 24'hFF0000);\n        wait_idle();\n\n        if (read_pixel(20, 20) == 24'hFF0000 && \n            read_pixel(35, 30) == 24'hFF0000 && \n            read_pixel(59, 49) == 24'hFF0000 && \n            read_pixel(19, 20) == 24'h000000 && \n            read_pixel(60, 50) == 24'h000000) begin\n            $display(\"  -> PASS: Red rectangle correctly rasterized with boundary clipping.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Rectangle pixel mismatch.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 3: Green Circle (CX=100, CY=50, R=25, Color=#00FF00)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 3] Green Circle Rasterization (Center=100,50, Radius=25)...\");\n        send_command(2'b01, 8'd100, 7'd50, 8'd25, 7'd0, 8'd0, 7'd0, 24'h00FF00);\n        wait_idle();\n\n        if (read_pixel(100, 50) == 24'h00FF00 &&  // Center\n            read_pixel(100, 25) == 24'h00FF00 &&  // Top edge\n            read_pixel(100, 75) == 24'h00FF00 &&  // Bottom edge\n            read_pixel(75, 50)  == 24'h00FF00 &&  // Left edge\n            read_pixel(125, 50) == 24'h00FF00 &&  // Right edge\n            read_pixel(100, 20) == 24'h000000 &&  // Outside top\n            read_pixel(130, 50) == 24'h000000) begin // Outside right\n            $display(\"  -> PASS: Green circle rasterized using squared-distance equation.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Circle coverage error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 4: Blue Triangle (V0=30,80, V1=80,80, V2=55,110, Color=#0000FF)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 4] Blue Triangle Rasterization (Pineda Edge Function)...\");\n        send_command(2'b10, 8'd30, 7'd80, 8'd80, 7'd80, 8'd55, 7'd110, 24'h0000FF);\n        wait_idle();\n\n        if (read_pixel(55, 90) == 24'h0000FF &&  // Interior\n            read_pixel(55, 80) == 24'h0000FF &&  // Top edge\n            read_pixel(55, 110)== 24'h0000FF &&  // Bottom vertex\n            read_pixel(25, 80) == 24'h000000 &&  // Outside left\n            read_pixel(85, 80) == 24'h000000) begin // Outside right\n            $display(\"  -> PASS: Blue triangle rasterized with signed edge arithmetic.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Triangle rasterization error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 5: Overlapping Shapes & Z-Order Verification\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 5] Overlapping Shapes (Yellow Square over Green Circle)...\");\n        // Draw Yellow square at (95, 45, W=10, H=10, Color=#FFFF00)\n        send_command(2'b00, 8'd95, 7'd45, 8'd10, 7'd10, 8'd0, 7'd0, 24'hFFFF00);\n        wait_idle();\n\n        if (read_pixel(95, 45) == 24'hFFFF00 &&  // Overwritten by yellow\n            read_pixel(100, 50) == 24'hFFFF00 && // Overwritten by yellow\n            read_pixel(120, 50) == 24'h00FF00) begin // Still green circle\n            $display(\"  -> PASS: Overlapping geometry correctly respects command order.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Overlapping pixel order error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 6: Command FIFO Backpressure & Burst Queueing\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 6] Command FIFO Burst Enqueue & Handshake...\");\n        // Send a burst of 3 small rectangles without waiting for completion\n        send_command(2'b00, 8'd130, 7'd10, 8'd5, 7'd5, 8'd0, 7'd0, 24'hFF00FF);\n        send_command(2'b00, 8'd140, 7'd10, 8'd5, 7'd5, 8'd0, 7'd0, 24'h00FFFF);\n        send_command(2'b00, 8'd130, 7'd20, 8'd5, 7'd5, 8'd0, 7'd0, 24'hFFFFFF);\n        wait_idle();\n\n        if (read_pixel(130, 10) == 24'hFF00FF && \n            read_pixel(140, 10) == 24'h00FFFF && \n            read_pixel(130, 20) == 24'hFFFFFF) begin\n            $display(\"  -> PASS: FIFO burst queue handled without data loss.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Burst command FIFO dropped commands.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 7: Display Controller Scanning & Video Synchronization\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 7] Display Controller Virtual Raster Scanning...\");\n        // Run simulation for 250 clocks to observe HSYNC / VSYNC / DE progression\n        repeat (250) @(posedge clk);\n\n        if (disp_hsync !== 1'bx && disp_vsync !== 1'bx && disp_de !== 1'bx) begin\n            $display(\"  -> PASS: Display raster timing signals valid and active.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Display controller signal undefined.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // Summary\n        $display(\"=================================================================\");\n        $display(\"   MINIGPU VERIFICATION SUMMARY: %0d PASSED, %0d FAILED          \", tests_passed, tests_failed);\n        if (tests_failed == 0) begin\n            $display(\"   *** ALL RTL TESTS COMPLETED SUCCESSFULLY (PASS) ***          \");\n        end else begin\n            $display(\"   *** VERIFICATION SUITE DETECTED REGRESSION (FAIL) ***        \");\n        end\n        $display(\"=================================================================\");\n\n        $finish;\n    end\n\nendmodule\n",
  "tb_rectangle.v": "// =============================================================================\n// Project: EcrioniX MiniGPU\n// Module:  tb_rectangle\n// File:    tb_rectangle.v\n// Purpose: Unit Testbench for Hardware Rectangle Rasterizer & Clipping\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_rectangle;\n    reg        enable;\n    reg  [7:0] cur_x;\n    reg  [6:0] cur_y;\n    reg  [7:0] rect_x;\n    reg  [6:0] rect_y;\n    reg  [7:0] rect_w;\n    reg  [6:0] rect_h;\n    wire       hit;\n\n    rectangle_rasterizer #(\n        .SCREEN_WIDTH(160),\n        .SCREEN_HEIGHT(120)\n    ) dut (\n        .enable(enable),\n        .cur_x(cur_x),\n        .cur_y(cur_y),\n        .rect_x(rect_x),\n        .rect_y(rect_y),\n        .rect_w(rect_w),\n        .rect_h(rect_h),\n        .hit(hit)\n    );\n\n    integer passed = 0;\n    integer failed = 0;\n\n    initial begin\n        $display(\"=== RECTANGLE RASTERIZER UNIT VERIFICATION ===\");\n        enable = 1;\n\n        // 1. Standard Rectangle at (10, 10, W=20, H=15)\n        rect_x = 10; rect_y = 10; rect_w = 20; rect_h = 15;\n        cur_x = 10; cur_y = 10; #1; if (hit) passed++; else failed++;\n        cur_x = 29; cur_y = 24; #1; if (hit) passed++; else failed++;\n        cur_x = 9;  cur_y = 10; #1; if (!hit) passed++; else failed++;\n        cur_x = 30; cur_y = 25; #1; if (!hit) passed++; else failed++;\n\n        // 2. Rectangle at Origin (0,0, W=5, H=5)\n        rect_x = 0; rect_y = 0; rect_w = 5; rect_h = 5;\n        cur_x = 0; cur_y = 0; #1; if (hit) passed++; else failed++;\n        cur_x = 4; cur_y = 4; #1; if (hit) passed++; else failed++;\n        cur_x = 5; cur_y = 5; #1; if (!hit) passed++; else failed++;\n\n        // 3. One-Pixel Rectangle (50, 50, W=1, H=1)\n        rect_x = 50; rect_y = 50; rect_w = 1; rect_h = 1;\n        cur_x = 50; cur_y = 50; #1; if (hit) passed++; else failed++;\n        cur_x = 51; cur_y = 50; #1; if (!hit) passed++; else failed++;\n\n        // 4. Maximum Valid Boundary Rectangle (155, 115, W=5, H=5)\n        rect_x = 155; rect_y = 115; rect_w = 5; rect_h = 5;\n        cur_x = 159; cur_y = 119; #1; if (hit) passed++; else failed++;\n        cur_x = 160; cur_y = 119; #1; if (!hit) passed++; else failed++; // clipped\n\n        // 5. Rectangle completely outside display (200, 150, W=10, H=10)\n        rect_x = 200; rect_y = 125; rect_w = 10; rect_h = 10;\n        cur_x = 200; cur_y = 125; #1; if (!hit) passed++; else failed++;\n\n        $display(\"Rectangle Tests: %0d PASSED, %0d FAILED\", passed, failed);\n        $finish;\n    end\nendmodule\n",
  "tb_circle.v": "// =============================================================================\n// Project: EcrioniX MiniGPU\n// Module:  tb_circle\n// File:    tb_circle.v\n// Purpose: Unit Testbench for Hardware Circle Rasterizer (Squared Distance)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_circle;\n    reg        enable;\n    reg  [7:0] cur_x;\n    reg  [6:0] cur_y;\n    reg  [7:0] circ_cx;\n    reg  [6:0] circ_cy;\n    reg  [7:0] circ_r;\n    wire       hit;\n\n    circle_rasterizer #(\n        .SCREEN_WIDTH(160),\n        .SCREEN_HEIGHT(120)\n    ) dut (\n        .enable(enable),\n        .cur_x(cur_x),\n        .cur_y(cur_y),\n        .circ_cx(circ_cx),\n        .circ_cy(circ_cy),\n        .circ_r(circ_r),\n        .hit(hit)\n    );\n\n    integer passed = 0;\n    integer failed = 0;\n\n    initial begin\n        $display(\"=== CIRCLE RASTERIZER UNIT VERIFICATION ===\");\n        enable = 1;\n\n        // 1. Standard Circle (CX=50, CY=50, R=10)\n        circ_cx = 50; circ_cy = 50; circ_r = 10;\n        cur_x = 50; cur_y = 50; #1; if (hit) passed++; else failed++; // Center\n        cur_x = 50; cur_y = 40; #1; if (hit) passed++; else failed++; // Top\n        cur_x = 50; cur_y = 60; #1; if (hit) passed++; else failed++; // Bottom\n        cur_x = 40; cur_y = 50; #1; if (hit) passed++; else failed++; // Left\n        cur_x = 60; cur_y = 50; #1; if (hit) passed++; else failed++; // Right\n        cur_x = 50; cur_y = 39; #1; if (!hit) passed++; else failed++; // Outside top\n        cur_x = 61; cur_y = 50; #1; if (!hit) passed++; else failed++; // Outside right\n\n        // 2. Symmetry verification (dx=6, dy=8 -> 36+64=100 <= 100)\n        cur_x = 56; cur_y = 58; #1; if (hit) passed++; else failed++; // (+6, +8)\n        cur_x = 44; cur_y = 58; #1; if (hit) passed++; else failed++; // (-6, +8)\n        cur_x = 56; cur_y = 42; #1; if (hit) passed++; else failed++; // (+6, -8)\n        cur_x = 44; cur_y = 42; #1; if (hit) passed++; else failed++; // (-6, -8)\n\n        // 3. Small radius zero (single pixel at center)\n        circ_cx = 20; circ_cy = 20; circ_r = 0;\n        cur_x = 20; cur_y = 20; #1; if (hit) passed++; else failed++;\n        cur_x = 21; cur_y = 20; #1; if (!hit) passed++; else failed++;\n\n        // 4. Boundary clipping (circle at right edge CX=158, CY=60, R=10)\n        circ_cx = 158; circ_cy = 60; circ_r = 10;\n        cur_x = 159; cur_y = 60; #1; if (hit) passed++; else failed++;\n        cur_x = 160; cur_y = 60; #1; if (!hit) passed++; else failed++; // outside screen\n\n        $display(\"Circle Tests: %0d PASSED, %0d FAILED\", passed, failed);\n        $finish;\n    end\nendmodule\n",
  "tb_triangle.v": "// =============================================================================\n// Project: EcrioniX MiniGPU\n// Module:  tb_triangle\n// File:    tb_triangle.v\n// Purpose: Unit Testbench for Pineda Edge-Function Triangle Rasterizer\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_triangle;\n    reg        enable;\n    reg  [7:0] cur_x;\n    reg  [6:0] cur_y;\n    reg  [7:0] v0_x, v1_x, v2_x;\n    reg  [6:0] v0_y, v1_y, v2_y;\n    wire       hit;\n\n    triangle_rasterizer #(\n        .SCREEN_WIDTH(160),\n        .SCREEN_HEIGHT(120)\n    ) dut (\n        .enable(enable),\n        .cur_x(cur_x),\n        .cur_y(cur_y),\n        .v0_x(v0_x), .v0_y(v0_y),\n        .v1_x(v1_x), .v1_y(v1_y),\n        .v2_x(v2_x), .v2_y(v2_y),\n        .hit(hit)\n    );\n\n    integer passed = 0;\n    integer failed = 0;\n\n    initial begin\n        $display(\"=== TRIANGLE RASTERIZER UNIT VERIFICATION ===\");\n        enable = 1;\n\n        // 1. Clockwise (CW) Right Triangle: V0(10,10), V1(30,10), V2(10,30)\n        v0_x = 10; v0_y = 10;\n        v1_x = 30; v1_y = 10;\n        v2_x = 10; v2_y = 30;\n        cur_x = 12; cur_y = 12; #1; if (hit) passed++; else failed++; // Interior\n        cur_x = 10; cur_y = 10; #1; if (hit) passed++; else failed++; // Vertex 0\n        cur_x = 30; cur_y = 10; #1; if (hit) passed++; else failed++; // Vertex 1\n        cur_x = 10; cur_y = 30; #1; if (hit) passed++; else failed++; // Vertex 2\n        cur_x = 25; cur_y = 25; #1; if (!hit) passed++; else failed++; // Outside hypotenuse\n\n        // 2. Counter-Clockwise (CCW) Winding Triangle: V0(10,10), V1(10,30), V2(30,10)\n        v0_x = 10; v0_y = 10;\n        v1_x = 10; v1_y = 30;\n        v2_x = 30; v2_y = 10;\n        cur_x = 12; cur_y = 12; #1; if (hit) passed++; else failed++; // Interior in CCW\n        cur_x = 25; cur_y = 25; #1; if (!hit) passed++; else failed++; // Outside\n\n        // 3. Degenerate Triangle (Collinear points: 10,10 to 30,30)\n        v0_x = 10; v0_y = 10;\n        v1_x = 20; v1_y = 20;\n        v2_x = 30; v2_y = 30;\n        cur_x = 15; cur_y = 15; #1; if (!hit) passed++; else failed++; // Rejected\n\n        $display(\"Triangle Tests: %0d PASSED, %0d FAILED\", passed, failed);\n        $finish;\n    end\nendmodule\n",
  "tb_cmd_fifo.v": "// =============================================================================\n// Project: EcrioniX MiniGPU\n// Module:  tb_cmd_fifo\n// File:    tb_cmd_fifo.v\n// Purpose: Unit Testbench for Command FIFO Buffer & Backpressure Handling\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_cmd_fifo;\n    reg         clk;\n    reg         rst_n;\n    reg         wr_en;\n    reg  [85:0] wr_data;\n    reg         rd_en;\n    wire [85:0] rd_data;\n    wire        empty;\n    wire        full;\n    wire [4:0]  count;\n\n    command_fifo #(\n        .DEPTH(4),\n        .WIDTH(86),\n        .ADDR_BITS(2)\n    ) dut (\n        .clk(clk),\n        .rst_n(rst_n),\n        .wr_en(wr_en),\n        .wr_data(wr_data),\n        .rd_en(rd_en),\n        .rd_data(rd_data),\n        .empty(empty),\n        .full(full),\n        .count(count)\n    );\n\n    always #5 clk = ~clk;\n\n    integer passed = 0;\n    integer failed = 0;\n\n    initial begin\n        $display(\"=== COMMAND FIFO UNIT VERIFICATION ===\");\n        clk = 0; rst_n = 0; wr_en = 0; rd_en = 0; wr_data = 0;\n        #15 rst_n = 1; #10;\n\n        // 1. Initial State: Empty\n        if (empty && !full && count == 0) passed++; else failed++;\n\n        // 2. Enqueue 4 items to fill FIFO\n        @(posedge clk); wr_en <= 1; wr_data <= 86'hA1;\n        @(posedge clk); wr_en <= 1; wr_data <= 86'hB2;\n        @(posedge clk); wr_en <= 1; wr_data <= 86'hC3;\n        @(posedge clk); wr_en <= 1; wr_data <= 86'hD4;\n        @(posedge clk); wr_en <= 0;\n        #1;\n        if (!empty && full && count == 4) passed++; else failed++;\n\n        // 3. FIFO head data inspection\n        if (rd_data == 86'hA1) passed++; else failed++;\n\n        // 4. Dequeue 1 item\n        @(posedge clk); rd_en <= 1;\n        @(posedge clk); rd_en <= 0;\n        #1;\n        if (!empty && !full && count == 3 && rd_data == 86'hB2) passed++; else failed++;\n\n        // 5. Simultaneous Enqueue & Dequeue\n        @(posedge clk); wr_en <= 1; wr_data <= 86'hE5; rd_en <= 1;\n        @(posedge clk); wr_en <= 0; rd_en <= 0;\n        #1;\n        if (count == 3 && rd_data == 86'hC3) passed++; else failed++;\n\n        $display(\"Command FIFO Tests: %0d PASSED, %0d FAILED\", passed, failed);\n        $finish;\n    end\nendmodule\n",
  "tb_framebuffer.v": "// =============================================================================\n// Project: EcrioniX MiniGPU\n// Module:  tb_framebuffer\n// File:    tb_framebuffer.v\n// Purpose: Unit Testbench for Dual-Port Synchronous Framebuffer Memory\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_framebuffer;\n    reg         clk;\n    reg         rst_n;\n    reg         we_a;\n    reg  [14:0] addr_a;\n    reg  [23:0] din_a;\n    reg         re_b;\n    reg  [14:0] addr_b;\n    wire [23:0] dout_b;\n\n    framebuffer #(\n        .WIDTH(24),\n        .SIZE(19200),\n        .ADDR_BITS(15)\n    ) dut (\n        .clk(clk),\n        .rst_n(rst_n),\n        .we_a(we_a),\n        .addr_a(addr_a),\n        .din_a(din_a),\n        .re_b(re_b),\n        .addr_b(addr_b),\n        .dout_b(dout_b)\n    );\n\n    always #5 clk = ~clk;\n\n    integer passed = 0;\n    integer failed = 0;\n\n    initial begin\n        $display(\"=== FRAMEBUFFER MEMORY UNIT VERIFICATION ===\");\n        clk = 0; rst_n = 0; we_a = 0; addr_a = 0; din_a = 0; re_b = 0; addr_b = 0;\n        #15 rst_n = 1; #10;\n\n        // 1. Initial State: Read address 0 -> 0x000000\n        @(posedge clk); re_b <= 1; addr_b <= 15'd0;\n        @(posedge clk); re_b <= 0;\n        #1; if (dout_b == 24'h000000) passed++; else failed++;\n\n        // 2. Write to Port A at Address 500 (Pixel 500 = RGB 0xFF55AA)\n        @(posedge clk); we_a <= 1; addr_a <= 15'd500; din_a <= 24'hFF55AA;\n        @(posedge clk); we_a <= 0;\n\n        // 3. Read back from Port B at Address 500 (1-cycle read latency)\n        @(posedge clk); re_b <= 1; addr_b <= 15'd500;\n        @(posedge clk); re_b <= 0;\n        #1; if (dout_b == 24'hFF55AA) passed++; else failed++;\n\n        // 4. Memory boundary test (Maximum address 19,199)\n        @(posedge clk); we_a <= 1; addr_a <= 15'd19199; din_a <= 24'h123456;\n        @(posedge clk); we_a <= 0;\n        @(posedge clk); re_b <= 1; addr_b <= 15'd19199;\n        @(posedge clk); re_b <= 0;\n        #1; if (dout_b == 24'h123456) passed++; else failed++;\n\n        $display(\"Framebuffer Tests: %0d PASSED, %0d FAILED\", passed, failed);\n        $finish;\n    end\nendmodule\n",
  "tb_display.v": "// =============================================================================\n// Project: EcrioniX MiniGPU\n// Module:  tb_display\n// File:    tb_display.v\n// Purpose: Unit Testbench for Virtual Display Controller & Raster Scanning\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_display;\n    reg         clk;\n    reg         rst_n;\n    wire [14:0] fb_read_addr;\n    wire        fb_read_en;\n    reg  [23:0] fb_read_data;\n    wire [7:0]  disp_x;\n    wire [6:0]  disp_y;\n    wire [23:0] rgb_out;\n    wire        hsync;\n    wire        vsync;\n    wire        display_enable;\n    wire        frame_tick;\n\n    display_controller #(\n        .H_ACTIVE(160),\n        .H_TOTAL(200),\n        .V_ACTIVE(120),\n        .V_TOTAL(130)\n    ) dut (\n        .clk(clk),\n        .rst_n(rst_n),\n        .fb_read_addr(fb_read_addr),\n        .fb_read_en(fb_read_en),\n        .fb_read_data(fb_read_data),\n        .disp_x(disp_x),\n        .disp_y(disp_y),\n        .rgb_out(rgb_out),\n        .hsync(hsync),\n        .vsync(vsync),\n        .display_enable(display_enable),\n        .frame_tick(frame_tick)\n    );\n\n    always #5 clk = ~clk;\n\n    integer passed = 0;\n    integer failed = 0;\n\n    initial begin\n        $display(\"=== DISPLAY CONTROLLER UNIT VERIFICATION ===\");\n        clk = 0; rst_n = 0; fb_read_data = 24'hAABBCC;\n        #15 rst_n = 1;\n\n        // Run through visible area and verify display_enable and coordinates\n        repeat (10) @(posedge clk);\n        if (display_enable && disp_x < 160 && disp_y < 120 && rgb_out == 24'hAABBCC) passed++; else failed++;\n\n        // Advance to horizontal blanking (clocks 165 to 195)\n        repeat (180) @(posedge clk);\n        if (!display_enable) passed++; else failed++;\n\n        $display(\"Display Controller Tests: %0d PASSED, %0d FAILED\", passed, failed);\n        $finish;\n    end\nendmodule\n",
  "combined_minigpu_sim.v": "// =============================================================================\n// Project: EcrioniX MiniGPU - Complete Monolithic Simulation Source\n// Synthesizable 2D Graphics Processor RTL + Verification Testbench\n// =============================================================================\n\n// --- BEGIN MODULE: cmd_interface.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  cmd_interface\n// File:    cmd_interface.v\n// Purpose: Host Command Interface with Ready/Valid Handshake & FIFO Packing\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule cmd_interface (\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Host interface ports\n    input  wire        cmd_valid_in,\n    output wire        cmd_ready_out,\n    input  wire [1:0]  cmd_type_in,    // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [7:0]  param_x0_in,    // X0 / Rect X / Circ CX / Tri X0\n    input  wire [6:0]  param_y0_in,    // Y0 / Rect Y / Circ CY / Tri Y0\n    input  wire [7:0]  param_x1_in,    // X1 / Rect W / Circ R  / Tri X1\n    input  wire [6:0]  param_y1_in,    // Y1 / Rect H / Unused  / Tri Y1\n    input  wire [7:0]  param_x2_in,    // X2 / Unused / Unused  / Tri X2\n    input  wire [6:0]  param_y2_in,    // Y2 / Unused / Unused  / Tri Y2\n    input  wire [23:0] param_color_in, // RGB888 Color\n\n    // Command FIFO write interface\n    input  wire        fifo_full,\n    output wire        fifo_wr_en,\n    output wire [85:0] fifo_wr_data\n);\n\n    // MiniGPU is ready to accept host commands when FIFO is not full\n    assign cmd_ready_out = !fifo_full;\n\n    // Write to FIFO on valid handshake\n    assign fifo_wr_en = cmd_valid_in && cmd_ready_out;\n\n    // Pack 86-bit command packet\n    // [85:84] : Command type (2 bits)\n    // [83:76] : X0 (8 bits)\n    // [75:69] : Y0 (7 bits)\n    // [68:61] : X1 (8 bits)\n    // [60:54] : Y1 (7 bits)\n    // [53:46] : X2 (8 bits)\n    // [45:39] : Y2 (7 bits)\n    // [38:15] : Color RGB888 (24 bits)\n    // [14:0]  : Reserved (15 bits)\n    assign fifo_wr_data = {\n        cmd_type_in,     // [85:84]\n        param_x0_in,     // [83:76]\n        param_y0_in,     // [75:69]\n        param_x1_in,     // [68:61]\n        param_y1_in,     // [60:54]\n        param_x2_in,     // [53:46]\n        param_y2_in,     // [45:39]\n        param_color_in,  // [38:15]\n        15'd0            // [14:0]\n    };\n\nendmodule\n\n\n// --- BEGIN MODULE: command_fifo.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  command_fifo\n// File:    command_fifo.v\n// Purpose: Synchronous Circular FIFO for Host Drawing Commands\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule command_fifo #(\n    parameter DEPTH     = 16,\n    parameter WIDTH     = 86,\n    parameter ADDR_BITS = 4\n)(\n    input  wire                  clk,\n    input  wire                  rst_n,\n\n    // Write Port\n    input  wire                  wr_en,\n    input  wire [WIDTH-1:0]      wr_data,\n\n    // Read Port\n    input  wire                  rd_en,\n    output wire [WIDTH-1:0]      rd_data,\n\n    // Status Flags\n    output wire                  empty,\n    output wire                  full,\n    output reg  [ADDR_BITS:0]    count\n);\n\n    reg [WIDTH-1:0]     mem [0:DEPTH-1];\n    reg [ADDR_BITS-1:0] wr_ptr;\n    reg [ADDR_BITS-1:0] rd_ptr;\n\n    assign empty = (count == {(ADDR_BITS+1){1'b0}});\n    assign full  = (count == DEPTH);\n\n    // Read data directly available at head of FIFO\n    assign rd_data = mem[rd_ptr];\n\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            wr_ptr <= {ADDR_BITS{1'b0}};\n            rd_ptr <= {ADDR_BITS{1'b0}};\n            count  <= {(ADDR_BITS+1){1'b0}};\n            for (i = 0; i < DEPTH; i = i + 1) begin\n                mem[i] <= {WIDTH{1'b0}};\n            end\n        end else begin\n            // Write action\n            if (wr_en && !full) begin\n                mem[wr_ptr] <= wr_data;\n                wr_ptr      <= (wr_ptr == DEPTH - 1) ? {ADDR_BITS{1'b0}} : wr_ptr + 1'b1;\n            end\n\n            // Read action\n            if (rd_en && !empty) begin\n                rd_ptr <= (rd_ptr == DEPTH - 1) ? {ADDR_BITS{1'b0}} : rd_ptr + 1'b1;\n            end\n\n            // Counter update\n            case ({wr_en && !full, rd_en && !empty})\n                2'b10: count <= count + 1'b1;\n                2'b01: count <= count - 1'b1;\n                default: count <= count; // 2'b00 or 2'b11 (simultaneous r/w)\n            endcase\n        end\n    end\n\nendmodule\n\n\n// --- BEGIN MODULE: rectangle_rasterizer.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  rectangle_rasterizer\n// File:    rectangle_rasterizer.v\n// Purpose: Hardware Rectangle Coverage & Clipping Rasterizer\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule rectangle_rasterizer #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire       enable,\n    input  wire [7:0] cur_x,\n    input  wire [6:0] cur_y,\n    input  wire [7:0] rect_x,\n    input  wire [6:0] rect_y,\n    input  wire [7:0] rect_w,\n    input  wire [6:0] rect_h,\n    output wire       hit\n);\n\n    wire [8:0] right_edge  = {1'b0, rect_x} + {1'b0, rect_w};\n    wire [7:0] bottom_edge = {1'b0, rect_y} + {1'b0, rect_h};\n\n    wire inside_x = (cur_x >= rect_x) && ({1'b0, cur_x} < right_edge);\n    wire inside_y = (cur_y >= rect_y) && ({1'b0, cur_y} < bottom_edge);\n    wire valid_screen = (cur_x < SCREEN_WIDTH) && (cur_y < SCREEN_HEIGHT);\n\n    assign hit = enable && inside_x && inside_y && valid_screen && (rect_w > 8'd0) && (rect_h > 7'd0);\n\nendmodule\n\n\n// --- BEGIN MODULE: circle_rasterizer.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  circle_rasterizer\n// File:    circle_rasterizer.v\n// Purpose: Hardware Circle Coverage Engine with Squared-Distance Arithmetic\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule circle_rasterizer #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire       enable,\n    input  wire [7:0] cur_x,\n    input  wire [6:0] cur_y,\n    input  wire [7:0] circ_cx,\n    input  wire [6:0] circ_cy,\n    input  wire [7:0] circ_r,\n    output wire       hit\n);\n\n    // Compute signed offsets from circle center\n    wire signed [9:0] dx = $signed({2'b00, cur_x}) - $signed({2'b00, circ_cx});\n    wire signed [9:0] dy = $signed({3'b000, cur_y}) - $signed({3'b000, circ_cy});\n\n    // Compute squared terms with 20-bit precision (prevents any overflow)\n    wire [19:0] dx_sq   = $unsigned(dx * dx);\n    wire [19:0] dy_sq   = $unsigned(dy * dy);\n    wire [19:0] dist_sq = dx_sq + dy_sq;\n    wire [19:0] r_sq    = $unsigned({12'd0, circ_r} * {12'd0, circ_r});\n\n    wire valid_screen = (cur_x < SCREEN_WIDTH) && (cur_y < SCREEN_HEIGHT);\n\n    // Coverage test: dx^2 + dy^2 <= r^2\n    assign hit = enable && valid_screen && (dist_sq <= r_sq);\n\nendmodule\n\n\n// --- BEGIN MODULE: triangle_rasterizer.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  triangle_rasterizer\n// File:    triangle_rasterizer.v\n// Purpose: Pineda Edge-Function Triangle Rasterizer (Signed Fixed-Point)\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule triangle_rasterizer #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire       enable,\n    input  wire [7:0] cur_x,\n    input  wire [6:0] cur_y,\n    input  wire [7:0] v0_x,\n    input  wire [6:0] v0_y,\n    input  wire [7:0] v1_x,\n    input  wire [6:0] v1_y,\n    input  wire [7:0] v2_x,\n    input  wire [6:0] v2_y,\n    output wire       hit\n);\n\n    // Signed extension for vertices and current coordinate\n    wire signed [10:0] px = $signed({3'b000, cur_x});\n    wire signed [10:0] py = $signed({4'b0000, cur_y});\n\n    wire signed [10:0] x0 = $signed({3'b000, v0_x});\n    wire signed [10:0] y0 = $signed({4'b0000, v0_y});\n    wire signed [10:0] x1 = $signed({3'b000, v1_x});\n    wire signed [10:0] y1 = $signed({4'b0000, v1_y});\n    wire signed [10:0] x2 = $signed({3'b000, v2_x});\n    wire signed [10:0] y2 = $signed({4'b0000, v2_y});\n\n    // Edge vectors\n    wire signed [10:0] dx01 = x1 - x0;\n    wire signed [10:0] dy01 = y1 - y0;\n\n    wire signed [10:0] dx12 = x2 - x1;\n    wire signed [10:0] dy12 = y2 - y1;\n\n    wire signed [10:0] dx20 = x0 - x2;\n    wire signed [10:0] dy20 = y0 - y2;\n\n    // Cross products for edge functions\n    // E01(p) = (px - x0) * dy01 - (py - y0) * dx01\n    // E12(p) = (px - x1) * dy12 - (py - y1) * dx12\n    // E20(p) = (px - x2) * dy20 - (py - y2) * dx20\n    wire signed [21:0] e01 = (px - x0) * dy01 - (py - y0) * dx01;\n    wire signed [21:0] e12 = (px - x1) * dy12 - (py - y1) * dx12;\n    wire signed [21:0] e20 = (px - x2) * dy20 - (py - y2) * dx20;\n\n    // Triangle winding check: all positive or all negative\n    wire all_pos = (e01 >= 22'sd0) && (e12 >= 22'sd0) && (e20 >= 22'sd0);\n    wire all_neg = (e01 <= 22'sd0) && (e12 <= 22'sd0) && (e20 <= 22'sd0);\n\n    // Reject degenerate triangles where all 3 vertices are collinear or identical\n    wire non_degenerate = (e01 != 22'sd0) || (e12 != 22'sd0) || (e20 != 22'sd0);\n\n    wire valid_screen = (cur_x < SCREEN_WIDTH) && (cur_y < SCREEN_HEIGHT);\n\n    assign hit = enable && valid_screen && (all_pos || all_neg) && non_degenerate;\n\nendmodule\n\n\n// --- BEGIN MODULE: pixel_color_generator.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  pixel_color_generator\n// File:    pixel_color_generator.v\n// Purpose: Hardware Pixel Color Formatting & Qualification\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule pixel_color_generator (\n    input  wire [1:0]  cmd_type,       // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [23:0] shape_color,    // RGB888 Color\n    input  wire        shape_hit,      // Hit from active rasterizer\n    output wire        pixel_valid,    // Qualified pixel ready to write\n    output wire [23:0] pixel_color     // Qualified 24-bit RGB\n);\n\n    // For Clear command (2'b11), every pixel in the screen grid is valid.\n    // For Shapes (2'b00, 2'b01, 2'b10), only pixels that pass the coverage test are valid.\n    wire is_clear = (cmd_type == 2'b11);\n\n    assign pixel_valid = is_clear || shape_hit;\n    assign pixel_color = shape_color;\n\nendmodule\n\n\n// --- BEGIN MODULE: framebuffer.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  framebuffer\n// File:    framebuffer.v\n// Purpose: True Dual-Port Synchronous Video Memory (19,200 x 24-bit RGB888)\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule framebuffer #(\n    parameter WIDTH     = 24,\n    parameter SIZE      = 19200,   // 160 x 120 pixels\n    parameter ADDR_BITS = 15       // 2^15 = 32768 > 19200\n)(\n    input  wire                 clk,\n    input  wire                 rst_n,\n\n    // Port A: Render Write Port\n    input  wire                 we_a,\n    input  wire [ADDR_BITS-1:0] addr_a,\n    input  wire [WIDTH-1:0]     din_a,\n\n    // Port B: Display Read Port\n    input  wire                 re_b,\n    input  wire [ADDR_BITS-1:0] addr_b,\n    output reg  [WIDTH-1:0]     dout_b\n);\n\n    // Synthesizable RAM block\n    reg [WIDTH-1:0] mem [0:SIZE-1];\n\n    integer i;\n\n    // Port A Write Operation\n    always @(posedge clk) begin\n        if (we_a && (addr_a < SIZE)) begin\n            mem[addr_a] <= din_a;\n        end\n    end\n\n    // Port B Read Operation (Synchronous 1-cycle read latency)\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            dout_b <= {WIDTH{1'b0}};\n        end else begin\n            if (re_b) begin\n                if (addr_b < SIZE) begin\n                    dout_b <= mem[addr_b];\n                end else begin\n                    dout_b <= {WIDTH{1'b0}};\n                end\n            end\n        end\n    end\n\n    // Power-up initialization for simulation\n    initial begin\n        for (i = 0; i < SIZE; i = i + 1) begin\n            mem[i] = {WIDTH{1'b0}};\n        end\n    end\n\nendmodule\n\n\n// --- BEGIN MODULE: command_decoder.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  command_decoder\n// File:    command_decoder.v\n// Purpose: Hardware Command Decoding, Parameter Validation & Bounding-Box Setup\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule command_decoder #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Interface with Command FIFO\n    input  wire        fifo_empty,\n    input  wire [85:0] fifo_data,\n    output reg         fifo_rd_en,\n\n    // Interface with Rasterizer Controller\n    input  wire        raster_idle,\n    input  wire        cmd_done,\n    output reg         cmd_valid_out,\n    output reg  [1:0]  cmd_type_out,\n\n    // Unpacked Shape Coordinates\n    output reg  [7:0]  shape_x0,\n    output reg  [6:0]  shape_y0,\n    output reg  [7:0]  shape_x1,\n    output reg  [6:0]  shape_y1,\n    output reg  [7:0]  shape_x2,\n    output reg  [6:0]  shape_y2,\n    output reg  [23:0] shape_color,\n\n    // Clipped Bounding-Box Limits\n    output reg  [7:0]  bbox_min_x,\n    output reg  [7:0]  bbox_max_x,\n    output reg  [6:0]  bbox_min_y,\n    output reg  [6:0]  bbox_max_y\n);\n\n    // Unpack raw fields from FIFO packet\n    wire [1:0]  raw_type  = fifo_data[85:84];\n    wire [7:0]  raw_x0    = fifo_data[83:76];\n    wire [6:0]  raw_y0    = fifo_data[75:69];\n    wire [7:0]  raw_x1    = fifo_data[68:61];\n    wire [6:0]  raw_y1    = fifo_data[60:54];\n    wire [7:0]  raw_x2    = fifo_data[53:46];\n    wire [6:0]  raw_y2    = fifo_data[45:39];\n    wire [23:0] raw_color = fifo_data[38:15];\n\n    // Combinational Bounding-Box Calculation\n    reg [7:0] calc_min_x;\n    reg [7:0] calc_max_x;\n    reg [6:0] calc_min_y;\n    reg [6:0] calc_max_y;\n\n    // Helper functions for min/max\n    function [7:0] min3_8(input [7:0] a, input [7:0] b, input [7:0] c);\n        reg [7:0] m;\n        begin\n            m = (a < b) ? a : b;\n            min3_8 = (m < c) ? m : c;\n        end\n    endfunction\n\n    function [7:0] max3_8(input [7:0] a, input [7:0] b, input [7:0] c);\n        reg [7:0] m;\n        begin\n            m = (a > b) ? a : b;\n            max3_8 = (m > c) ? m : c;\n        end\n    endfunction\n\n    function [6:0] min3_7(input [6:0] a, input [6:0] b, input [6:0] c);\n        reg [6:0] m;\n        begin\n            m = (a < b) ? a : b;\n            min3_7 = (m < c) ? m : c;\n        end\n    endfunction\n\n    function [6:0] max3_7(input [6:0] a, input [6:0] b, input [6:0] c);\n        reg [6:0] m;\n        begin\n            m = (a > b) ? a : b;\n            max3_7 = (m > c) ? m : c;\n        end\n    endfunction\n\n    always @(*) begin\n        case (raw_type)\n            2'b00: begin // Rectangle: X, Y, Width, Height\n                calc_min_x = (raw_x0 < SCREEN_WIDTH) ? raw_x0 : 8'd0;\n                calc_max_x = (({1'b0, raw_x0} + {1'b0, raw_x1}) > SCREEN_WIDTH) ? \n                             8'd159 : (raw_x1 > 8'd0 ? raw_x0 + raw_x1 - 1'b1 : raw_x0);\n                calc_min_y = (raw_y0 < SCREEN_HEIGHT) ? raw_y0 : 7'd0;\n                calc_max_y = (({1'b0, raw_y0} + {1'b0, raw_y1}) > SCREEN_HEIGHT) ? \n                             7'd119 : (raw_y1 > 7'd0 ? raw_y0 + raw_y1 - 1'b1 : raw_y0);\n            end\n\n            2'b01: begin // Circle: Center X, Center Y, Radius\n                calc_min_x = (raw_x0 >= raw_x1) ? (raw_x0 - raw_x1) : 8'd0;\n                calc_max_x = (({1'b0, raw_x0} + {1'b0, raw_x1}) > 9'd159) ? 8'd159 : (raw_x0 + raw_x1);\n                calc_min_y = (raw_y0 >= raw_x1[6:0]) ? (raw_y0 - raw_x1[6:0]) : 7'd0;\n                calc_max_y = (({1'b0, raw_y0} + {1'b0, raw_x1[6:0]}) > 8'd119) ? 7'd119 : (raw_y0 + raw_x1[6:0]);\n            end\n\n            2'b10: begin // Triangle: V0(x0,y0), V1(x1,y1), V2(x2,y2)\n                calc_min_x = min3_8(raw_x0, raw_x1, raw_x2);\n                calc_max_x = (max3_8(raw_x0, raw_x1, raw_x2) < SCREEN_WIDTH) ? \n                              max3_8(raw_x0, raw_x1, raw_x2) : 8'd159;\n                calc_min_y = min3_7(raw_y0, raw_y1, raw_y2);\n                calc_max_y = (max3_7(raw_y0, raw_y1, raw_y2) < SCREEN_HEIGHT) ? \n                              max3_7(raw_y0, raw_y1, raw_y2) : 7'd119;\n            end\n\n            2'b11: begin // Clear Screen (Full Framebuffer)\n                calc_min_x = 8'd0;\n                calc_max_x = 8'd159;\n                calc_min_y = 7'd0;\n                calc_max_y = 7'd119;\n            end\n        endcase\n    end\n\n    // FSM for Decoder Dispatches\n    localparam DEC_IDLE = 2'b00;\n    localparam DEC_WAIT = 2'b01;\n    localparam DEC_POP  = 2'b10;\n\n    reg [1:0] dec_state;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            dec_state     <= DEC_IDLE;\n            fifo_rd_en    <= 1'b0;\n            cmd_valid_out <= 1'b0;\n            cmd_type_out  <= 2'b00;\n            shape_x0      <= 8'd0;\n            shape_y0      <= 7'd0;\n            shape_x1      <= 8'd0;\n            shape_y1      <= 7'd0;\n            shape_x2      <= 8'd0;\n            shape_y2      <= 7'd0;\n            shape_color   <= 24'd0;\n            bbox_min_x    <= 8'd0;\n            bbox_max_x    <= 8'd0;\n            bbox_min_y    <= 7'd0;\n            bbox_max_y    <= 7'd0;\n        end else begin\n            fifo_rd_en <= 1'b0; // Default pulse\n\n            case (dec_state)\n                DEC_IDLE: begin\n                    cmd_valid_out <= 1'b0;\n                    if (!fifo_empty && raster_idle) begin\n                        cmd_type_out  <= raw_type;\n                        shape_x0      <= raw_x0;\n                        shape_y0      <= raw_y0;\n                        shape_x1      <= raw_x1;\n                        shape_y1      <= raw_y1;\n                        shape_x2      <= raw_x2;\n                        shape_y2      <= raw_y2;\n                        shape_color   <= raw_color;\n                        bbox_min_x    <= calc_min_x;\n                        bbox_max_x    <= calc_max_x;\n                        bbox_min_y    <= calc_min_y;\n                        bbox_max_y    <= calc_max_y;\n\n                        cmd_valid_out <= 1'b1;\n                        dec_state     <= DEC_WAIT;\n                    end\n                end\n\n                DEC_WAIT: begin\n                    if (cmd_done) begin\n                        cmd_valid_out <= 1'b0;\n                        fifo_rd_en    <= 1'b1; // Dequeue command from FIFO\n                        dec_state     <= DEC_POP;\n                    end else if (!raster_idle) begin\n                        cmd_valid_out <= 1'b0; // Rasterizer has acknowledged\n                    end\n                end\n\n                DEC_POP: begin\n                    fifo_rd_en <= 1'b0;\n                    dec_state  <= DEC_IDLE; // Allow 1 clock cycle for FIFO to advance rd_ptr\n                end\n\n                default: dec_state <= DEC_IDLE;\n            endcase\n        end\n    end\n\nendmodule\n\n\n// --- BEGIN MODULE: rasterizer_controller.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  rasterizer_controller\n// File:    rasterizer_controller.v\n// Purpose: Hardware Rasterization FSM, Coordinate Traversal & Pixel Dispatch\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule rasterizer_controller #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Command Interface from Decoder\n    input  wire        cmd_valid,\n    input  wire [1:0]  cmd_type,       // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [7:0]  bbox_min_x,\n    input  wire [7:0]  bbox_max_x,\n    input  wire [6:0]  bbox_min_y,\n    input  wire [6:0]  bbox_max_y,\n    input  wire [23:0] shape_color,\n    output reg         cmd_done,\n\n    // Interface to Shape Rasterizers\n    output reg         eval_enable,\n    output reg  [7:0]  cur_pixel_x,\n    output reg  [6:0]  cur_pixel_y,\n    input  wire        shape_hit,      // Hit result from active rasterizer\n    input  wire        pixel_valid,    // Qualified pixel from pixel_color_generator\n\n    // Framebuffer Write Interface (Port A)\n    input  wire        fb_ready,       // Framebuffer memory ready / no stall\n    output reg         fb_we,\n    output reg  [14:0] fb_addr,\n    output reg  [23:0] fb_data,\n\n    // Status and Telemetry\n    output wire        raster_idle,\n    output reg  [2:0]  raster_state,\n    output reg  [31:0] total_pixels_rendered,\n    output reg  [15:0] total_commands_done\n);\n\n    // FSM State Encoding\n    localparam STATE_IDLE      = 3'b000;\n    localparam STATE_SETUP     = 3'b001;\n    localparam STATE_RASTERIZE = 3'b010;\n    localparam STATE_WRITE     = 3'b011;\n    localparam STATE_COMPLETE  = 3'b100;\n\n    assign raster_idle = (raster_state == STATE_IDLE);\n\n    // Latched command boundaries and attributes\n    reg [1:0]  latched_type;\n    reg [7:0]  latched_min_x, latched_max_x;\n    reg [6:0]  latched_min_y, latched_max_y;\n    reg [23:0] latched_color;\n\n    // Framebuffer address arithmetic: y * 160 + x = (y << 7) + (y << 5) + x\n    wire [14:0] calc_addr = ({8'd0, cur_pixel_y} << 7) + \n                            ({8'd0, cur_pixel_y} << 5) + \n                            {7'd0, cur_pixel_x};\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            raster_state          <= STATE_IDLE;\n            eval_enable           <= 1'b0;\n            cur_pixel_x           <= 8'd0;\n            cur_pixel_y           <= 7'd0;\n            fb_we                 <= 1'b0;\n            fb_addr               <= 15'd0;\n            fb_data               <= 24'd0;\n            cmd_done              <= 1'b0;\n            latched_type          <= 2'b00;\n            latched_min_x         <= 8'd0;\n            latched_max_x         <= 8'd0;\n            latched_min_y         <= 7'd0;\n            latched_max_y         <= 7'd0;\n            latched_color         <= 24'd0;\n            total_pixels_rendered <= 32'd0;\n            total_commands_done   <= 16'd0;\n        end else begin\n            cmd_done <= 1'b0; // Default pulse\n            fb_we    <= 1'b0; // Default no-write\n\n            case (raster_state)\n                STATE_IDLE: begin\n                    eval_enable <= 1'b0;\n                    if (cmd_valid) begin\n                        latched_type  <= cmd_type;\n                        latched_min_x <= bbox_min_x;\n                        latched_max_x <= bbox_max_x;\n                        latched_min_y <= bbox_min_y;\n                        latched_max_y <= bbox_max_y;\n                        latched_color <= shape_color;\n                        raster_state  <= STATE_SETUP;\n                    end\n                end\n\n                STATE_SETUP: begin\n                    // Initialize scan cursor to top-left of clipped bounding box\n                    cur_pixel_x  <= latched_min_x;\n                    cur_pixel_y  <= latched_min_y;\n                    eval_enable  <= 1'b1;\n                    raster_state <= STATE_RASTERIZE;\n                end\n\n                STATE_RASTERIZE: begin\n                    eval_enable <= 1'b1;\n\n                    // Evaluate if current pixel is covered\n                    if (pixel_valid && fb_ready) begin\n                        // Dispatch write to Framebuffer Port A\n                        fb_we                 <= 1'b1;\n                        fb_addr               <= calc_addr;\n                        fb_data               <= latched_color;\n                        total_pixels_rendered <= total_pixels_rendered + 1'b1;\n                    end\n\n                    // Advance coordinates (scanline traversal)\n                    if (cur_pixel_x < latched_max_x) begin\n                        cur_pixel_x <= cur_pixel_x + 1'b1;\n                    end else begin\n                        cur_pixel_x <= latched_min_x;\n                        if (cur_pixel_y < latched_max_y) begin\n                            cur_pixel_y <= cur_pixel_y + 1'b1;\n                        end else begin\n                            // Reached end of bounding box\n                            eval_enable  <= 1'b0;\n                            raster_state <= STATE_COMPLETE;\n                        end\n                    end\n                end\n\n                STATE_COMPLETE: begin\n                    eval_enable         <= 1'b0;\n                    cmd_done            <= 1'b1;\n                    total_commands_done <= total_commands_done + 1'b1;\n                    raster_state        <= STATE_IDLE;\n                end\n\n                default: raster_state <= STATE_IDLE;\n            endcase\n        end\n    end\n\nendmodule\n\n\n// --- BEGIN MODULE: display_controller.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  display_controller\n// File:    display_controller.v\n// Purpose: Virtual Display Raster Timing Generator & Framebuffer Port B Scanner\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule display_controller #(\n    // Virtual Display Timing Parameters (160 x 120 Resolution)\n    parameter H_ACTIVE      = 160,\n    parameter H_FRONT_PORCH = 8,\n    parameter H_SYNC        = 16,\n    parameter H_BACK_PORCH  = 16,\n    parameter H_TOTAL       = 200, // 160 + 8 + 16 + 16\n\n    parameter V_ACTIVE      = 120,\n    parameter V_FRONT_PORCH = 2,\n    parameter V_SYNC        = 4,\n    parameter V_BACK_PORCH  = 4,\n    parameter V_TOTAL       = 130  // 120 + 2 + 4 + 4\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // Framebuffer Port B Interface\n    output wire [14:0] fb_read_addr,\n    output wire        fb_read_en,\n    input  wire [23:0] fb_read_data,\n\n    // Display Output Signals\n    output reg  [7:0]  disp_x,\n    output reg  [6:0]  disp_y,\n    output reg  [23:0] rgb_out,\n    output reg         hsync,\n    output reg         vsync,\n    output reg         display_enable,\n    output reg         frame_tick\n);\n\n    // Scan counters\n    reg [7:0] h_count; // 0 .. 199\n    reg [7:0] v_count; // 0 .. 129\n\n    // Pre-fetch coordinate logic (1 clock cycle ahead to match SRAM read latency)\n    wire [7:0] next_h = (h_count == H_TOTAL - 1) ? 8'd0 : h_count + 1'b1;\n    wire [7:0] next_v = (h_count == H_TOTAL - 1) ? \n                        ((v_count == V_TOTAL - 1) ? 8'd0 : v_count + 1'b1) : v_count;\n\n    wire next_active = (next_h < H_ACTIVE) && (next_v < V_ACTIVE);\n\n    // Framebuffer read address: next_v * 160 + next_h = (next_v << 7) + (next_v << 5) + next_h\n    assign fb_read_addr = ({8'd0, next_v[6:0]} << 7) + \n                          ({8'd0, next_v[6:0]} << 5) + \n                          {7'd0, next_h};\n\n    assign fb_read_en = next_active;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            h_count        <= 8'd0;\n            v_count        <= 8'd0;\n            disp_x         <= 8'd0;\n            disp_y         <= 7'd0;\n            rgb_out        <= 24'd0;\n            hsync          <= 1'b1;\n            vsync          <= 1'b1;\n            display_enable <= 1'b0;\n            frame_tick     <= 1'b0;\n        end else begin\n            // Advance horizontal and vertical scan counters\n            if (h_count == H_TOTAL - 1) begin\n                h_count <= 8'd0;\n                if (v_count == V_TOTAL - 1) begin\n                    v_count    <= 8'd0;\n                    frame_tick <= 1'b1; // New frame pulse\n                end else begin\n                    v_count    <= v_count + 1'b1;\n                    frame_tick <= 1'b0;\n                end\n            end else begin\n                h_count    <= h_count + 1'b1;\n                frame_tick <= 1'b0;\n            end\n\n            // Horizontal sync (active low during sync interval)\n            hsync <= !( (h_count >= H_ACTIVE + H_FRONT_PORCH) && \n                        (h_count <  H_ACTIVE + H_FRONT_PORCH + H_SYNC) );\n\n            // Vertical sync (active low during sync interval)\n            vsync <= !( (v_count >= V_ACTIVE + V_FRONT_PORCH) && \n                        (v_count <  V_ACTIVE + V_FRONT_PORCH + V_SYNC) );\n\n            // Display enable (active during visible frame region)\n            display_enable <= (h_count < H_ACTIVE) && (v_count < V_ACTIVE);\n\n            // Output coordinates and pixel color\n            if (h_count < H_ACTIVE && v_count < V_ACTIVE) begin\n                disp_x  <= h_count;\n                disp_y  <= v_count[6:0];\n                rgb_out <= fb_read_data; // Framebuffer data arrived 1 cycle after address\n            end else begin\n                disp_x  <= 8'd0;\n                disp_y  <= 7'd0;\n                rgb_out <= 24'd0; // Blanking during porch/sync intervals\n            end\n        end\n    end\n\nendmodule\n\n\n// --- BEGIN MODULE: minigpu_top.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  minigpu_top\n// File:    minigpu_top.v\n// Purpose: Top-Level Integration of 2D Graphics Processing Architecture\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule minigpu_top #(\n    parameter SCREEN_WIDTH  = 160,\n    parameter SCREEN_HEIGHT = 120,\n    parameter FIFO_DEPTH    = 16,\n    parameter FIFO_ADDR     = 4\n)(\n    input  wire        clk,\n    input  wire        rst_n,\n\n    // =========================================================================\n    // 1. Host Command Interface (Handshake + Parameters)\n    // =========================================================================\n    input  wire        cmd_valid_in,\n    output wire        cmd_ready_out,\n    input  wire [1:0]  cmd_type_in,    // 00=Rect, 01=Circ, 10=Tri, 11=Clear\n    input  wire [7:0]  param_x0_in,    // X0 / Rect X / Circ CX / Tri X0\n    input  wire [6:0]  param_y0_in,    // Y0 / Rect Y / Circ CY / Tri Y0\n    input  wire [7:0]  param_x1_in,    // X1 / Rect W / Circ R  / Tri X1\n    input  wire [6:0]  param_y1_in,    // Y1 / Rect H / Unused  / Tri Y1\n    input  wire [7:0]  param_x2_in,    // X2 / Unused / Unused  / Tri X2\n    input  wire [6:0]  param_y2_in,    // Y2 / Unused / Unused  / Tri Y2\n    input  wire [23:0] param_color_in, // RGB888 Color\n\n    // =========================================================================\n    // 2. Video Display Output (Raster Scanning Stream)\n    // =========================================================================\n    output wire        disp_hsync,\n    output wire        disp_vsync,\n    output wire        disp_de,\n    output wire [23:0] disp_rgb,\n    output wire [7:0]  disp_x,\n    output wire [6:0]  disp_y,\n    output wire        disp_frame_tick,\n\n    // =========================================================================\n    // 3. Telemetry & Hardware Status Signals\n    // =========================================================================\n    output wire        status_fifo_empty,\n    output wire        status_fifo_full,\n    output wire [FIFO_ADDR:0] status_fifo_count,\n    output wire        status_raster_idle,\n    output wire [2:0]  status_raster_state,\n    output wire [7:0]  status_cur_x,\n    output wire [6:0]  status_cur_y,\n    output wire        status_shape_hit,\n    output wire        status_pixel_valid,\n    output wire        status_fb_we,\n    output wire [14:0] status_fb_addr,\n    output wire [23:0] status_fb_wdata,\n    output wire [31:0] status_total_rendered,\n    output wire [15:0] status_total_cmds\n);\n\n    // -------------------------------------------------------------------------\n    // Internal Wires & Busses\n    // -------------------------------------------------------------------------\n    // Host Interface <-> FIFO\n    wire        fifo_wr_en;\n    wire [85:0] fifo_wr_data;\n    wire        fifo_rd_en;\n    wire [85:0] fifo_rd_data;\n    wire        fifo_empty;\n    wire        fifo_full;\n    wire [FIFO_ADDR:0] fifo_count;\n\n    // FIFO <-> Decoder <-> Rasterizer Controller\n    wire        raster_idle;\n    wire        cmd_done;\n    wire        dec_cmd_valid;\n    wire [1:0]  dec_cmd_type;\n    wire [7:0]  dec_shape_x0, dec_shape_x1, dec_shape_x2;\n    wire [6:0]  dec_shape_y0, dec_shape_y1, dec_shape_y2;\n    wire [23:0] dec_shape_color;\n    wire [7:0]  dec_bbox_min_x, dec_bbox_max_x;\n    wire [6:0]  dec_bbox_min_y, dec_bbox_max_y;\n\n    // Rasterizer Controller <-> Shape Rasterizers\n    wire        eval_enable;\n    wire [7:0]  cur_pixel_x;\n    wire [6:0]  cur_pixel_y;\n    wire        rect_hit;\n    wire        circ_hit;\n    wire        tri_hit;\n    reg         active_shape_hit;\n\n    // Pixel Color Generator\n    wire        gen_pixel_valid;\n    wire [23:0] gen_pixel_color;\n\n    // Framebuffer Port A (Render Write)\n    wire        fb_we;\n    wire [14:0] fb_waddr;\n    wire [23:0] fb_wdata;\n\n    // Framebuffer Port B (Display Read)\n    wire        fb_re_b;\n    wire [14:0] fb_raddr_b;\n    wire [23:0] fb_rdata_b;\n\n    // -------------------------------------------------------------------------\n    // 1. Host Command Interface\n    // -------------------------------------------------------------------------\n    cmd_interface u_cmd_interface (\n        .clk            (clk),\n        .rst_n          (rst_n),\n        .cmd_valid_in   (cmd_valid_in),\n        .cmd_ready_out  (cmd_ready_out),\n        .cmd_type_in    (cmd_type_in),\n        .param_x0_in    (param_x0_in),\n        .param_y0_in    (param_y0_in),\n        .param_x1_in    (param_x1_in),\n        .param_y1_in    (param_y1_in),\n        .param_x2_in    (param_x2_in),\n        .param_y2_in    (param_y2_in),\n        .param_color_in (param_color_in),\n        .fifo_full      (fifo_full),\n        .fifo_wr_en     (fifo_wr_en),\n        .fifo_wr_data   (fifo_wr_data)\n    );\n\n    // -------------------------------------------------------------------------\n    // 2. Command FIFO Buffer\n    // -------------------------------------------------------------------------\n    command_fifo #(\n        .DEPTH     (FIFO_DEPTH),\n        .WIDTH     (86),\n        .ADDR_BITS (FIFO_ADDR)\n    ) u_command_fifo (\n        .clk       (clk),\n        .rst_n     (rst_n),\n        .wr_en     (fifo_wr_en),\n        .wr_data   (fifo_wr_data),\n        .rd_en     (fifo_rd_en),\n        .rd_data   (fifo_rd_data),\n        .empty     (fifo_empty),\n        .full      (fifo_full),\n        .count     (fifo_count)\n    );\n\n    // -------------------------------------------------------------------------\n    // 3. Command Decoder & Range Validator\n    // -------------------------------------------------------------------------\n    command_decoder #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_command_decoder (\n        .clk           (clk),\n        .rst_n         (rst_n),\n        .fifo_empty    (fifo_empty),\n        .fifo_data     (fifo_rd_data),\n        .fifo_rd_en    (fifo_rd_en),\n        .raster_idle   (raster_idle),\n        .cmd_done      (cmd_done),\n        .cmd_valid_out (dec_cmd_valid),\n        .cmd_type_out  (dec_cmd_type),\n        .shape_x0      (dec_shape_x0),\n        .shape_y0      (dec_shape_y0),\n        .shape_x1      (dec_shape_x1),\n        .shape_y1      (dec_shape_y1),\n        .shape_x2      (dec_shape_x2),\n        .shape_y2      (dec_shape_y2),\n        .shape_color   (dec_shape_color),\n        .bbox_min_x    (dec_bbox_min_x),\n        .bbox_max_x    (dec_bbox_max_x),\n        .bbox_min_y    (dec_bbox_min_y),\n        .bbox_max_y    (dec_bbox_max_y)\n    );\n\n    // -------------------------------------------------------------------------\n    // 4. Shape Rasterization Submodules\n    // -------------------------------------------------------------------------\n    rectangle_rasterizer #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_rect_rasterizer (\n        .enable        (eval_enable && (dec_cmd_type == 2'b00)),\n        .cur_x         (cur_pixel_x),\n        .cur_y         (cur_pixel_y),\n        .rect_x        (dec_shape_x0),\n        .rect_y        (dec_shape_y0),\n        .rect_w        (dec_shape_x1),\n        .rect_h        (dec_shape_y1),\n        .hit           (rect_hit)\n    );\n\n    circle_rasterizer #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_circ_rasterizer (\n        .enable        (eval_enable && (dec_cmd_type == 2'b01)),\n        .cur_x         (cur_pixel_x),\n        .cur_y         (cur_pixel_y),\n        .circ_cx       (dec_shape_x0),\n        .circ_cy       (dec_shape_y0),\n        .circ_r        (dec_shape_x1),\n        .hit           (circ_hit)\n    );\n\n    triangle_rasterizer #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_tri_rasterizer (\n        .enable        (eval_enable && (dec_cmd_type == 2'b10)),\n        .cur_x         (cur_pixel_x),\n        .cur_y         (cur_pixel_y),\n        .v0_x          (dec_shape_x0),\n        .v0_y          (dec_shape_y0),\n        .v1_x          (dec_shape_x1),\n        .v1_y          (dec_shape_y1),\n        .v2_x          (dec_shape_x2),\n        .v2_y          (dec_shape_y2),\n        .hit           (tri_hit)\n    );\n\n    // Active shape hit multiplexer\n    always @(*) begin\n        case (dec_cmd_type)\n            2'b00:   active_shape_hit = rect_hit;\n            2'b01:   active_shape_hit = circ_hit;\n            2'b10:   active_shape_hit = tri_hit;\n            2'b11:   active_shape_hit = 1'b1; // Clear screen fills entire bbox\n            default: active_shape_hit = 1'b0;\n        endcase\n    end\n\n    // -------------------------------------------------------------------------\n    // 5. Pixel Color Generator\n    // -------------------------------------------------------------------------\n    pixel_color_generator u_color_gen (\n        .cmd_type      (dec_cmd_type),\n        .shape_color   (dec_shape_color),\n        .shape_hit     (active_shape_hit),\n        .pixel_valid   (gen_pixel_valid),\n        .pixel_color   (gen_pixel_color)\n    );\n\n    // -------------------------------------------------------------------------\n    // 6. Rasterization Controller\n    // -------------------------------------------------------------------------\n    rasterizer_controller #(\n        .SCREEN_WIDTH  (SCREEN_WIDTH),\n        .SCREEN_HEIGHT (SCREEN_HEIGHT)\n    ) u_raster_controller (\n        .clk           (clk),\n        .rst_n         (rst_n),\n        .cmd_valid     (dec_cmd_valid),\n        .cmd_type      (dec_cmd_type),\n        .bbox_min_x    (dec_bbox_min_x),\n        .bbox_max_x    (dec_bbox_max_x),\n        .bbox_min_y    (dec_bbox_min_y),\n        .bbox_max_y    (dec_bbox_max_y),\n        .shape_color   (dec_shape_color),\n        .cmd_done      (cmd_done),\n        .eval_enable   (eval_enable),\n        .cur_pixel_x   (cur_pixel_x),\n        .cur_pixel_y   (cur_pixel_y),\n        .shape_hit     (active_shape_hit),\n        .pixel_valid   (gen_pixel_valid),\n        .fb_ready      (1'b1), // Dual-port SRAM always ready\n        .fb_we         (fb_we),\n        .fb_addr       (fb_waddr),\n        .fb_data       (fb_wdata),\n        .raster_idle   (raster_idle),\n        .raster_state  (status_raster_state),\n        .total_pixels_rendered (status_total_rendered),\n        .total_commands_done   (status_total_cmds)\n    );\n\n    // -------------------------------------------------------------------------\n    // 7. Dual-Port Synchronous Framebuffer Memory (19,200 x 24-bit)\n    // -------------------------------------------------------------------------\n    framebuffer #(\n        .WIDTH     (24),\n        .SIZE      (SCREEN_WIDTH * SCREEN_HEIGHT),\n        .ADDR_BITS (15)\n    ) u_framebuffer (\n        .clk       (clk),\n        .rst_n     (rst_n),\n        // Port A: Render Write\n        .we_a      (fb_we),\n        .addr_a    (fb_waddr),\n        .din_a     (fb_wdata),\n        // Port B: Display Read\n        .re_b      (fb_re_b),\n        .addr_b    (fb_raddr_b),\n        .dout_b    (fb_rdata_b)\n    );\n\n    // -------------------------------------------------------------------------\n    // 8. Virtual Display Controller & Raster Scanner\n    // -------------------------------------------------------------------------\n    display_controller #(\n        .H_ACTIVE  (SCREEN_WIDTH),\n        .V_ACTIVE  (SCREEN_HEIGHT)\n    ) u_display_ctrl (\n        .clk            (clk),\n        .rst_n          (rst_n),\n        .fb_read_addr   (fb_raddr_b),\n        .fb_read_en     (fb_re_b),\n        .fb_read_data   (fb_rdata_b),\n        .disp_x         (disp_x),\n        .disp_y         (disp_y),\n        .rgb_out        (disp_rgb),\n        .hsync          (disp_hsync),\n        .vsync          (disp_vsync),\n        .display_enable (disp_de),\n        .frame_tick     (disp_frame_tick)\n    );\n\n    // -------------------------------------------------------------------------\n    // 9. Status & Telemetry Wiring\n    // -------------------------------------------------------------------------\n    assign status_fifo_empty   = fifo_empty;\n    assign status_fifo_full    = fifo_full;\n    assign status_fifo_count   = fifo_count;\n    assign status_raster_idle  = raster_idle;\n    assign status_cur_x        = cur_pixel_x;\n    assign status_cur_y        = cur_pixel_y;\n    assign status_shape_hit    = active_shape_hit;\n    assign status_pixel_valid  = gen_pixel_valid;\n    assign status_fb_we        = fb_we;\n    assign status_fb_addr      = fb_waddr;\n    assign status_fb_wdata     = fb_wdata;\n\nendmodule\n\n\n// --- BEGIN TESTBENCH: tb_minigpu_top.v ---\n// =============================================================================\n// Project: EcrioniX MiniGPU - Cycle-Accurate 2D Graphics Processor\n// Module:  tb_minigpu_top\n// File:    tb_minigpu_top.v\n// Purpose: Comprehensive Testbench & Hardware Verification Suite\n// Author:  EcrioniX Hardware Engineering Team (https://ecrionix.org)\n// =============================================================================\n\n`timescale 1ns / 1ps\n\nmodule tb_minigpu_top;\n\n    reg         clk;\n    reg         rst_n;\n\n    // Host Command Interface\n    reg         cmd_valid_in;\n    wire        cmd_ready_out;\n    reg  [1:0]  cmd_type_in;\n    reg  [7:0]  param_x0_in;\n    reg  [6:0]  param_y0_in;\n    reg  [7:0]  param_x1_in;\n    reg  [6:0]  param_y1_in;\n    reg  [7:0]  param_x2_in;\n    reg  [6:0]  param_y2_in;\n    reg  [23:0] param_color_in;\n\n    // Video Output\n    wire        disp_hsync;\n    wire        disp_vsync;\n    wire        disp_de;\n    wire [23:0] disp_rgb;\n    wire [7:0]  disp_x;\n    wire [6:0]  disp_y;\n    wire        disp_frame_tick;\n\n    // Status Signals\n    wire        status_fifo_empty;\n    wire        status_fifo_full;\n    wire [4:0]  status_fifo_count;\n    wire        status_raster_idle;\n    wire [2:0]  status_raster_state;\n    wire [7:0]  status_cur_x;\n    wire [6:0]  status_cur_y;\n    wire        status_shape_hit;\n    wire        status_pixel_valid;\n    wire        status_fb_we;\n    wire [14:0] status_fb_addr;\n    wire [23:0] status_fb_wdata;\n    wire [31:0] status_total_rendered;\n    wire [15:0] status_total_cmds;\n\n    // Instantiate Device Under Test (DUT)\n    minigpu_top #(\n        .SCREEN_WIDTH  (160),\n        .SCREEN_HEIGHT (120),\n        .FIFO_DEPTH    (16),\n        .FIFO_ADDR     (4)\n    ) dut (\n        .clk                   (clk),\n        .rst_n                 (rst_n),\n        .cmd_valid_in          (cmd_valid_in),\n        .cmd_ready_out         (cmd_ready_out),\n        .cmd_type_in           (cmd_type_in),\n        .param_x0_in           (param_x0_in),\n        .param_y0_in           (param_y0_in),\n        .param_x1_in           (param_x1_in),\n        .param_y1_in           (param_y1_in),\n        .param_x2_in           (param_x2_in),\n        .param_y2_in           (param_y2_in),\n        .param_color_in        (param_color_in),\n        .disp_hsync            (disp_hsync),\n        .disp_vsync            (disp_vsync),\n        .disp_de               (disp_de),\n        .disp_rgb              (disp_rgb),\n        .disp_x                (disp_x),\n        .disp_y                (disp_y),\n        .disp_frame_tick       (disp_frame_tick),\n        .status_fifo_empty     (status_fifo_empty),\n        .status_fifo_full      (status_fifo_full),\n        .status_fifo_count     (status_fifo_count),\n        .status_raster_idle    (status_raster_idle),\n        .status_raster_state   (status_raster_state),\n        .status_cur_x          (status_cur_x),\n        .status_cur_y          (status_cur_y),\n        .status_shape_hit      (status_shape_hit),\n        .status_pixel_valid    (status_pixel_valid),\n        .status_fb_we          (status_fb_we),\n        .status_fb_addr        (status_fb_addr),\n        .status_fb_wdata       (status_fb_wdata),\n        .status_total_rendered (status_total_rendered),\n        .status_total_cmds     (status_total_cmds)\n    );\n\n    // Clock Generation: 50 MHz simulation clock (20ns period)\n    always #10 clk = ~clk;\n\n    // Verification statistics\n    integer tests_passed = 0;\n    integer tests_failed = 0;\n\n    // Helper task to send drawing command\n    task send_command(\n        input [1:0]  c_type,\n        input [7:0]  x0, input [6:0] y0,\n        input [7:0]  x1, input [6:0] y1,\n        input [7:0]  x2, input [6:0] y2,\n        input [23:0] color\n    );\n        begin\n            @(posedge clk);\n            while (!cmd_ready_out) @(posedge clk);\n            cmd_valid_in   <= 1'b1;\n            cmd_type_in    <= c_type;\n            param_x0_in    <= x0;\n            param_y0_in    <= y0;\n            param_x1_in    <= x1;\n            param_y1_in    <= y1;\n            param_x2_in    <= x2;\n            param_y2_in    <= y2;\n            param_color_in <= color;\n            @(posedge clk);\n            cmd_valid_in   <= 1'b0;\n        end\n    endtask\n\n    // Helper task to wait until rasterizer finishes all commands\n    task wait_idle();\n        begin\n            repeat (3) @(posedge clk);\n            while (!status_fifo_empty || !status_raster_idle) @(posedge clk);\n            repeat (5) @(posedge clk);\n        end\n    endtask\n\n    // Helper function to read framebuffer pixel\n    function [23:0] read_pixel(input [7:0] x, input [6:0] y);\n        integer addr;\n        begin\n            addr = y * 160 + x;\n            read_pixel = dut.u_framebuffer.mem[addr];\n        end\n    endfunction\n\n    initial begin\n        $dumpfile(\"minigpu_sim.vcd\");\n        $dumpvars(0, tb_minigpu_top);\n\n        $display(\"=================================================================\");\n        $display(\"   ECRIONIX MINIGPU - CYCLE-ACCURATE RTL VERIFICATION SUITE      \");\n        $display(\"=================================================================\");\n\n        clk            = 0;\n        rst_n          = 0;\n        cmd_valid_in   = 0;\n        cmd_type_in    = 0;\n        param_x0_in    = 0;\n        param_y0_in    = 0;\n        param_x1_in    = 0;\n        param_y1_in    = 0;\n        param_x2_in    = 0;\n        param_y2_in    = 0;\n        param_color_in = 0;\n\n        // Apply Reset\n        #40;\n        rst_n = 1;\n        #20;\n\n        // ---------------------------------------------------------------------\n        // TEST 1: Clear Screen (Black Background #000000)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 1] Clear Screen with Background #000000...\");\n        send_command(2'b11, 8'd0, 7'd0, 8'd0, 7'd0, 8'd0, 7'd0, 24'h000000);\n        wait_idle();\n\n        if (read_pixel(0, 0) == 24'h000000 && \n            read_pixel(80, 60) == 24'h000000 && \n            read_pixel(159, 119) == 24'h000000) begin\n            $display(\"  -> PASS: Screen cleared to black (19,200 pixels initialized).\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Screen clear verification error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 2: Red Rectangle (X=20, Y=20, W=40, H=30, Color=#FF0000)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 2] Red Rectangle Rasterization (20,20 to 59,49)...\");\n        send_command(2'b00, 8'd20, 7'd20, 8'd40, 7'd30, 8'd0, 7'd0, 24'hFF0000);\n        wait_idle();\n\n        if (read_pixel(20, 20) == 24'hFF0000 && \n            read_pixel(35, 30) == 24'hFF0000 && \n            read_pixel(59, 49) == 24'hFF0000 && \n            read_pixel(19, 20) == 24'h000000 && \n            read_pixel(60, 50) == 24'h000000) begin\n            $display(\"  -> PASS: Red rectangle correctly rasterized with boundary clipping.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Rectangle pixel mismatch.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 3: Green Circle (CX=100, CY=50, R=25, Color=#00FF00)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 3] Green Circle Rasterization (Center=100,50, Radius=25)...\");\n        send_command(2'b01, 8'd100, 7'd50, 8'd25, 7'd0, 8'd0, 7'd0, 24'h00FF00);\n        wait_idle();\n\n        if (read_pixel(100, 50) == 24'h00FF00 &&  // Center\n            read_pixel(100, 25) == 24'h00FF00 &&  // Top edge\n            read_pixel(100, 75) == 24'h00FF00 &&  // Bottom edge\n            read_pixel(75, 50)  == 24'h00FF00 &&  // Left edge\n            read_pixel(125, 50) == 24'h00FF00 &&  // Right edge\n            read_pixel(100, 20) == 24'h000000 &&  // Outside top\n            read_pixel(130, 50) == 24'h000000) begin // Outside right\n            $display(\"  -> PASS: Green circle rasterized using squared-distance equation.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Circle coverage error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 4: Blue Triangle (V0=30,80, V1=80,80, V2=55,110, Color=#0000FF)\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 4] Blue Triangle Rasterization (Pineda Edge Function)...\");\n        send_command(2'b10, 8'd30, 7'd80, 8'd80, 7'd80, 8'd55, 7'd110, 24'h0000FF);\n        wait_idle();\n\n        if (read_pixel(55, 90) == 24'h0000FF &&  // Interior\n            read_pixel(55, 80) == 24'h0000FF &&  // Top edge\n            read_pixel(55, 110)== 24'h0000FF &&  // Bottom vertex\n            read_pixel(25, 80) == 24'h000000 &&  // Outside left\n            read_pixel(85, 80) == 24'h000000) begin // Outside right\n            $display(\"  -> PASS: Blue triangle rasterized with signed edge arithmetic.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Triangle rasterization error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 5: Overlapping Shapes & Z-Order Verification\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 5] Overlapping Shapes (Yellow Square over Green Circle)...\");\n        // Draw Yellow square at (95, 45, W=10, H=10, Color=#FFFF00)\n        send_command(2'b00, 8'd95, 7'd45, 8'd10, 7'd10, 8'd0, 7'd0, 24'hFFFF00);\n        wait_idle();\n\n        if (read_pixel(95, 45) == 24'hFFFF00 &&  // Overwritten by yellow\n            read_pixel(100, 50) == 24'hFFFF00 && // Overwritten by yellow\n            read_pixel(120, 50) == 24'h00FF00) begin // Still green circle\n            $display(\"  -> PASS: Overlapping geometry correctly respects command order.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Overlapping pixel order error.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 6: Command FIFO Backpressure & Burst Queueing\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 6] Command FIFO Burst Enqueue & Handshake...\");\n        // Send a burst of 3 small rectangles without waiting for completion\n        send_command(2'b00, 8'd130, 7'd10, 8'd5, 7'd5, 8'd0, 7'd0, 24'hFF00FF);\n        send_command(2'b00, 8'd140, 7'd10, 8'd5, 7'd5, 8'd0, 7'd0, 24'h00FFFF);\n        send_command(2'b00, 8'd130, 7'd20, 8'd5, 7'd5, 8'd0, 7'd0, 24'hFFFFFF);\n        wait_idle();\n\n        if (read_pixel(130, 10) == 24'hFF00FF && \n            read_pixel(140, 10) == 24'h00FFFF && \n            read_pixel(130, 20) == 24'hFFFFFF) begin\n            $display(\"  -> PASS: FIFO burst queue handled without data loss.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Burst command FIFO dropped commands.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // ---------------------------------------------------------------------\n        // TEST 7: Display Controller Scanning & Video Synchronization\n        // ---------------------------------------------------------------------\n        $display(\"[TEST 7] Display Controller Virtual Raster Scanning...\");\n        // Run simulation for 250 clocks to observe HSYNC / VSYNC / DE progression\n        repeat (250) @(posedge clk);\n\n        if (disp_hsync !== 1'bx && disp_vsync !== 1'bx && disp_de !== 1'bx) begin\n            $display(\"  -> PASS: Display raster timing signals valid and active.\");\n            tests_passed = tests_passed + 1;\n        end else begin\n            $display(\"  -> FAIL: Display controller signal undefined.\");\n            tests_failed = tests_failed + 1;\n        end\n\n        // Summary\n        $display(\"=================================================================\");\n        $display(\"   MINIGPU VERIFICATION SUMMARY: %0d PASSED, %0d FAILED          \", tests_passed, tests_failed);\n        if (tests_failed == 0) begin\n            $display(\"   *** ALL RTL TESTS COMPLETED SUCCESSFULLY (PASS) ***          \");\n        end else begin\n            $display(\"   *** VERIFICATION SUITE DETECTED REGRESSION (FAIL) ***        \");\n        end\n        $display(\"=================================================================\");\n\n        $finish;\n    end\n\nendmodule\n\n"
};
